  window.LESSONS["u2_l07"] = {"meta":{"grade":6,"subject":"수학","term":2,"unit":2,"unit_title":"공간과 입체","n":7,"title":"쌓은 모양을 알아봐요(1) — 위, 앞, 옆에서 본 모양","std":"[6수03-10] 쌓기나무로 만든 입체도형의 위, 앞, 옆에서 본 모양을 표현할 수 있고, 이러한 표현을 보고 입체도형의 모양을 추측할 수 있다.","duration_min":40,"lesson_format":"개념 차시 · 2세대 19장(7요소)","theme":"여러 방향에서 보는 공간","source":"2022 개정 수학 6-2 지도서 2단원(163~208쪽 · 『수학』 31~54 · 『수학익힘』 25~40) — 자기주도 원문 없이 지도서에서 세움 · 투영 회수 키 grade6/semester2/math/2단원_공간과입체/g6_math_u2_l07_쌓은모양을알아봐요1.html","src_key":"u2_l07"},"slides":[{"id":"s01","stage":"도입","block":"cover","data":{"title":"쌓은 모양을 알아봐요(1)\n세 판으로 떠올리기","emoji":"🖥️"},"suggested_extras":["v_l7_1"]},{"id":"s02","stage":"도입","block":"review","data":{"title":"지난 시간엔 무엇을 했나요?","content":"지난 시간에는 쌓은 모양을 **층별로** 나누어 개수를 구했어요. 오늘은 거꾸로 **위, 앞, 옆에서 본 모양**을 보고 쌓은 모양을 떠올려요.","items":[{"q":"층별로 나눈 그림에서 1층 모양은 무엇과 같을까요?","a":"위에서 본 모양"},{"q":"교과서 41쪽 1층 6개, 2층 3개, 3층 1개면 모두 몇 개일까요?","a":"10"},{"q":"교과서 42쪽 문제 4는 쌓기나무가 몇 개일까요?","a":"9"}],"from":"u2_l06"},"suggested_extras":["q_l7_1"]},{"id":"s03","stage":"도입","block":"motivate","data":{"scene_title":"컴퓨터로 쌓기나무 쌓기","desc":"친구들이 쌓은 모양을 고개를 들어 보기도 하고 허리를 숙여 보기도 해요. 컴퓨터의 「알지오매스 키즈」에서는 방향 버튼을 누르면 다른 방향에서 본 모양을 볼 수 있어요.","question":"위, 앞, 옆에서 본 모양만 보고 쌓은 모양을 떠올릴 수 있을까요? 실제 쌓기나무와 컴퓨터는 어떤 점이 같고 다를까요?","img":"assets/photo/math/computer_block_tool_screen.jpg","tnote":{"ask":["컴퓨터와 실제 쌓기나무의 같은 점은?","다른 점은?"],"watch":"세 판이면 늘 하나로 정해진다고 여기는 경우","min":3}},"suggested_extras":["q_l7_2","r_l7_1"]},{"id":"s04","stage":"전개","block":"concept","data":{"fig":{"k":"skp","h":[[0,1,0],[1,2,3],[0,1,0]],"show":["top","front","side"]},"title":"위에서 본 모양으로 1층 떠올리기","content":"교과서 44쪽 활동 1 — 위에서 본 모양을 보고 **1층 모양**을 먼저 떠올려요.\n십자 모양으로 1층에 5개를 깔아요.","tnote":{"ask":["1층에는 몇 개를 깔까요?","위에서 본 모양이 왜 1층 모양일까요?"],"watch":"앞에서 본 모양으로 1층을 정하는 경우","min":4}},"suggested_extras":["e_l7_1"]},{"id":"s05","stage":"전개","block":"concept","data":{"fig":{"k":"skp","h":[[0,1,0],[1,2,3],[0,1,0]],"show":["iso","top","front","side"]},"title":"앞과 옆으로 더 쌓을 곳 찾기","content":"앞에서 본 모양은 왼쪽부터 1층, 2층, 3층, 옆에서 본 모양은 앞줄부터 1층, 3층, 1층이에요.\n두 판이 만나는 자리를 찾으면 가운데 줄 가운데에 **1개**, 가운데 줄 오른쪽에 **2개**를 더 쌓아요.\n모두 5 + 1 + 2 = **8개**예요.","tnote":{"ask":["3층은 어느 자리일까요?","앞줄 가운데는 왜 1층일까요?"],"watch":"앞에서 본 모양을 앞줄 높이로 읽는 경우","min":4}},"suggested_extras":["t_l7_1"]},{"id":"s06","stage":"전개","block":"concept","data":{"fig":{"k":"tools","items":[{"name":"위에서 본 모양 → 1층"},{"name":"앞·옆에서 본 모양 → 더 쌓을 곳"},{"name":"쌓기나무·컴퓨터로 확인"}]},"title":"쌓아서 확인하기","content":"떠올린 모양이 맞는지 **쌓기나무나 컴퓨터**로 쌓아 보고, 다시 위, 앞, 옆에서 본 모양과 견주어요.\n컴퓨터로 쌓으면 뒤와 밑에서 본 모양도 쉽게 볼 수 있어요.","tnote":{"ask":["확인할 때 무엇과 견주나요?","컴퓨터로 쌓으면 좋은 점은?"],"watch":"떠올리기만 하고 확인하지 않는 경우","min":4}},"suggested_extras":["e_l7_2","t_l7_2"]},{"id":"s07","stage":"전개","block":"concept","data":{"fig":{"k":"skp","h":[[0,3,3],[2,2,0]],"show":["iso","top","front","side"]},"title":"세 판이 같아도 모양이 다를 수 있어요","content":"교과서 44쪽 문제 2 — 세 판에 맞는 모양을 찾으면 교과서 세 번째 모양(**10개**)이에요.\n그런데 앞줄 가운데가 **1개여도 2개여도** 세 판이 같아요.\n앞과 옆에서 본 모양은 **줄마다 가장 높은 층만** 알려 주기 때문이에요.","tnote":{"ask":["앞줄 가운데에 1개만 놓으면 세 판이 달라지나요?","왜 두 가지가 나올까요?"],"watch":"세 판이면 늘 하나로 정해진다고 여기는 경우","min":4}},"suggested_extras":["q_l7_3"]},{"id":"s08","stage":"전개","block":"misconception","data":{"title":"이런 생각을 조심해요","label":"자주 하는 생각","wrong":"위, 앞, 옆에서 본 모양이 같으면 쌓은 모양은 **반드시 같다**.","right":"앞과 옆에서 본 모양은 **줄마다 가장 높은 층**만 알려 줘요. 교과서 44쪽 문제 2는 앞줄 가운데가 1개여도 2개여도 세 판이 같아 **쌓은 모양이 두 가지**예요.","hint":"두 모양을 실제로 쌓아 세 방향에서 보게 하세요.","tnote":{"ask":["두 모양의 세 판을 그려 보면?","무엇이 달라야 판이 달라질까요?"],"watch":"세 판으로 개수를 늘 하나로 답하는 경우","min":3}},"suggested_extras":["x_l7_1","x_l7_2"]},{"id":"s09","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ①","scenario":{"icon":"🧊","body":"교과서 44쪽 활동 1의 위, 앞, 옆에서 본 모양이에요."},"question":"똑같이 쌓을 때 필요한 쌓기나무는 몇 개일까요?","fig":{"k":"skp","h":[[0,1,0],[1,2,3],[0,1,0]],"show":["top","front","side"]},"input":"count_input","answer":8,"note":"풀이: 1층 5개 · 가운데 줄 가운데 +1, 오른쪽 +2 → 8 → **8**"},"suggested_extras":["t_l7_3"]},{"id":"s10","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ②","scenario":{"icon":"🧊","body":"같은 세 판으로 떠올린 쌓은 모양이에요."},"question":"3층까지 쌓인 자리는 어디일까요?","fig":{"k":"skp","h":[[0,1,0],[1,2,3],[0,1,0]],"show":["top","front","side"]},"options":[{"text":"가운데 줄 왼쪽"},{"text":"가운데 줄 오른쪽","correct":true},{"text":"뒷줄 가운데"},{"text":"앞줄 가운데"}],"note":"풀이: 앞에서 본 3층은 오른쪽 줄 · 옆에서 본 3층은 가운데 줄 → **가운데 줄 오른쪽**"},"suggested_extras":["e_l7_3"]},{"id":"s11","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ③","scenario":{"icon":"🧊","body":"교과서 44쪽 문제 2의 위, 앞, 옆에서 본 모양이에요."},"question":"세 판에 맞게 쌓을 때 쌓기나무가 가장 적게 드는 경우는 몇 개일까요?","fig":{"k":"skp","h":[[0,3,3],[2,2,0]],"show":["top","front","side"]},"input":"count_input","answer":9,"note":"풀이: 정해지는 자리 2 + 3 + 3 = 8 · 앞줄 가운데 1개일 때 8 + 1 = 9 → **9**"},"suggested_extras":["q_l7_4"]},{"id":"s12","stage":"기본문제","block":"leveled_problem","data":{"title":"수준을 골라 풀어요","levels":{"기본":{"q":"세 판으로 쌓은 모양을 떠올릴 때 가장 먼저 보는 판은 무엇일까요?","a":"위에서 본 모양","steps":["위에서 본 모양 = 1층 모양","1층을 먼저 깔아요","위에서 본 모양"]},"도전":{"q":"교과서 44쪽 문제 2의 세 판에 맞는 쌓은 모양은 모두 몇 가지일까요?","a":"2","steps":["앞줄 가운데만 정해지지 않아요","1개 또는 2개","2가지"]},"심화":{"q":"세 판으로 쌓은 모양이 하나로 정해지지 않을 때 하나로 정하려면 어떤 조건을 더 알려 주면 좋을까요?","a":"여러 답 (예: 전체 쌓기나무 개수 · 특정 자리의 개수 · 위에서 본 모양에 수 쓰기)","open":true}},"tnote":{"ask":["기본에서 왜 위에서 본 모양부터일까요?","심화에서 낸 조건으로 하나로 정해지나요?"],"watch":"도전에서 1가지라고 하는 경우","min":5}},"suggested_extras":["q_l7_5","g_l7_1"]},{"id":"s13","stage":"응용문제","block":"offline_activity","data":{"title":"세 판 보고 쌓기 경주","type":"group","goal":"모둠이 세 판 카드를 보고 쌓기나무로 쌓은 뒤, 쌓기나무나 「알지오매스 키즈」로 세 판이 맞는지 확인하기","steps":["모둠마다 세 판 카드 한 장을 뽑는다","위에서 본 모양으로 1층을 깔고 앞·옆으로 더 쌓을 곳을 정한다","쌓은 모양을 세 방향에서 보거나 컴퓨터로 확인한다","다른 모양도 가능한지 찾아보고 발표한다"],"solo":["세 판 카드를 하나 고른다","공책에 위에서 본 모양을 그리고 자리마다 높이를 써 본다","쓴 높이로 앞·옆에서 본 모양을 다시 그려 카드와 견준다"],"materials":["쌓기나무","세 판 카드","태블릿(알지오매스 키즈)"],"minutes":8,"tnote":{"ask":["세 판이 모두 맞았나요?","다른 모양도 가능했나요?"],"watch":"앞에서 본 모양만 맞추고 끝내는 모둠","min":8}},"suggested_extras":["g_l7_2","t_l7_4"]},{"id":"s14","stage":"응용문제","block":"real_world","data":{"title":"3D 프린터 설계","scenario":{"icon":"🖨️","body":"3D 프린터로 물건을 만들 때 위, 앞, 옆에서 본 그림만으로는 속이 빈 곳이나 뒤쪽 모양이 정해지지 않아 설계 파일에 높이 정보를 함께 넣어요."},"content":"위, 앞, 옆에서 본 모양으로 쌓은 모양을 떠올릴 때는 **위에서 본 모양으로 1층**, **앞·옆으로 더 쌓을 곳**을 찾아요. 세 판이 같아도 모양이 **여러 가지**일 수 있어요."},"suggested_extras":["r_l7_2","r_l7_3"]},{"id":"s15","stage":"응용문제","block":"advanced_problem","data":{"title":"생각을 넓혀요","context":"『수학익힘』 35쪽 — 위, 앞, 옆에서 본 모양을 보고 쌓은 모양 두 개 가운데 하나를 골라요. 첫 번째 모양은 앞과 위에서 본 모양은 맞지만 옆에서 보면 다르게 보여요.","challenge":"후보 모양이 세 판에 맞는지 확인하는 방법은 무엇일까요?","note":"풀이: 후보 모양을 다시 위, 앞, 옆에서 본 모양으로 그려 주어진 세 판과 견주어요 · 하나라도 다르면 답이 아니에요 · **세 판을 모두 견주어요**","tnote":{"ask":["첫 번째 모양은 어느 판이 달랐나요?","두 판만 맞으면 될까요?"],"watch":"앞에서 본 모양만 견주는 경우","min":4}},"suggested_extras":["t_l7_5"]},{"id":"s16","stage":"정리","block":"exit_ticket","data":{"title":"오늘 확인해요","items":[{"q":"교과서 44쪽 활동 1의 세 판으로 떠올린 모양은 쌓기나무가 몇 개일까요?","a":"8"},{"q":"앞과 옆에서 본 모양은 줄마다 무엇을 알려 줄까요?","a":"가장 높은 층"},{"q":"교과서 44쪽 문제 2에서 앞줄 가운데에 놓을 수 있는 쌓기나무 개수를 모두 말하면 무엇일까요?","a":"1개, 2개"}],"self":["오늘 배운 것을 혼자 설명할 수 있어요","조금 헷갈려요","다시 배우고 싶어요"]},"suggested_extras":[]},{"id":"s17","stage":"정리","block":"summary","data":{"title":"오늘 배운 것","points":["위에서 본 모양으로 1층을 떠올려요.","앞과 옆에서 본 모양으로 더 쌓을 곳을 찾아요.","쌓기나무나 컴퓨터로 쌓아 세 판과 견주어 확인해요.","세 판이 같아도 쌓은 모양이 여러 가지일 수 있다는 것을 찾았다."],"arrows":["위 → 1층","앞·옆 → 더 쌓기","확인"]},"suggested_extras":["r_l7_1"]},{"id":"s18","stage":"정리","block":"self_assessment","data":{"title":"스스로 점검해요","items":["📚 지식·이해 — 세 판으로 쌓은 모양을 떠올리는 차례를 말할 수 있나요?","🔧 과정·기능 — 떠올린 모양을 쌓아 확인할 수 있나요?","💛 가치·태도 — 다른 모양도 가능한지 끝까지 찾아보려 했나요?"],"prompts":["실제 쌓기나무와 컴퓨터 가운데 더 편했던 것은?"]},"suggested_extras":["e_l7_3"]},{"id":"s19","stage":"정리","block":"next_lesson","data":{"title":"다음 시간엔","preview":"위에서 본 모양에 수를 쓴 그림과 층별로 나타낸 그림을 보고도 쌓은 모양을 떠올릴 수 있을까요? 네 가지 표현을 견주어 봐요.","emoji":"🧩"},"suggested_extras":["c_l7_1"]}],"extras":[{"id":"v_l7_1","type":"video","icon":"🎥","title":"세 판으로 쌓은 모양","url":"https://www.youtube.com/results?search_query=%EC%B4%88%EB%93%B1+6%ED%95%99%EB%85%84+%EC%9C%84+%EC%95%9E+%EC%98%86%EC%97%90%EC%84%9C+%EB%B3%B8+%EB%AA%A8%EC%96%91+%EB%B3%B4%EA%B3%A0+%EC%8C%93%EC%9D%80+%EB%AA%A8%EC%96%91+%EC%95%8C%EC%95%84%EB%B3%B4%EA%B8%B0","description":"알지오매스 키즈로 확인.","source":"유튜브 검색 (교사 사전 확인 권장)","fit_slides":["concept","motivate"]},{"id":"q_l7_1","type":"fun_question","icon":"💡","title":"먼저 볼 판","content":"어느 판을 먼저 볼까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l7_2","type":"fun_question","icon":"💡","title":"3층 자리","content":"3층은 어디일까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l7_3","type":"fun_question","icon":"💡","title":"컴퓨터","content":"컴퓨터로 쌓으면 무엇이 좋을까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l7_4","type":"fun_question","icon":"💡","title":"두 가지 모양","content":"세 판이 같은데 모양이 다를 수 있을까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l7_5","type":"fun_question","icon":"💡","title":"확인","content":"떠올린 모양은 어떻게 확인할까요?","fit_slides":["concept","basic_problem"]},{"id":"t_l7_1","type":"tip","icon":"🧩","title":"두 도구 모두","content":"실물 쌓기나무와 컴퓨터를 가능한 한 모두 경험하게 하세요(지도서 196).","fit_slides":["concept","misconception"]},{"id":"t_l7_2","type":"tip","icon":"🧩","title":"단계 설명","content":"떠올리지 못하면 쌓는 과정을 단계별로 말하게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l7_3","type":"tip","icon":"🧩","title":"여러 모양","content":"세 판이 같지만 모양이 여러 가지인 예를 찾게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l7_4","type":"tip","icon":"🧩","title":"단순한 모양","content":"어려워하면 더 단순한 모양부터 세 판을 그리게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l7_5","type":"tip","icon":"🧩","title":"디지털 도구","content":"실제 도구와 공학 도구의 장단점을 이야기하게 하세요.","fit_slides":["concept","misconception"]},{"id":"r_l7_1","type":"real_world","icon":"🌍","title":"3D 설계","content":"높이 정보가 필요한 까닭.","fit_slides":["real_world","summary"]},{"id":"r_l7_2","type":"real_world","icon":"🌍","title":"레고 설명서","content":"단계별 그림.","fit_slides":["real_world","summary"]},{"id":"r_l7_3","type":"real_world","icon":"🌍","title":"게임 맵 제작","content":"위·옆 화면으로 지형 만들기.","fit_slides":["real_world","summary"]},{"id":"g_l7_1","type":"game","icon":"🎮","title":"세 판 경주","content":"카드 보고 먼저 쌓기.","fit_slides":["leveled_problem","offline_activity"]},{"id":"g_l7_2","type":"game","icon":"🎮","title":"모양 찾아 잇기","content":"세 판과 쌓은 모양 잇기.","fit_slides":["leveled_problem","offline_activity"]},{"id":"x_l7_1","type":"misconception","icon":"⚠️","title":"늘 하나","content":"세 판이면 모양이 하나로 정해진다고 여기기.","fit_slides":["misconception","basic_problem"]},{"id":"x_l7_2","type":"misconception","icon":"⚠️","title":"앞줄 높이","content":"앞에서 본 모양을 앞줄 높이로 읽기.","fit_slides":["misconception","basic_problem"]},{"id":"e_l7_1","type":"example","icon":"📝","title":"활동 1 세 판","content":"십자 모양 세 판을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l7_2","type":"example","icon":"📝","title":"떠올린 모양","content":"8개로 쌓은 모양을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l7_3","type":"example","icon":"📝","title":"두 가지 모양","content":"문제 2의 9개·10개 모양을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"c_l7_1","type":"checklist","icon":"✅","title":"다음 시간 준비","content":"쌓기나무 12개를 챙깁니다.","fit_slides":["next_lesson"]}]};
  window.LESSONS["u2_l08"] = {"meta":{"grade":6,"subject":"수학","term":2,"unit":2,"unit_title":"공간과 입체","n":8,"title":"쌓은 모양을 알아봐요(2) — 수를 쓴 그림·층별 그림","std":"[6수03-10] 쌓기나무로 만든 입체도형의 위, 앞, 옆에서 본 모양을 표현할 수 있고, 이러한 표현을 보고 입체도형의 모양을 추측할 수 있다.","duration_min":40,"lesson_format":"개념 차시 · 2세대 19장(7요소)","theme":"여러 방향에서 보는 공간","source":"2022 개정 수학 6-2 지도서 2단원(163~208쪽 · 『수학』 31~54 · 『수학익힘』 25~40) — 자기주도 원문 없이 지도서에서 세움 · 투영 회수 키 grade6/semester2/math/2단원_공간과입체/g6_math_u2_l08_쌓은모양을알아봐요2.html","src_key":"u2_l08"},"slides":[{"id":"s01","stage":"도입","block":"cover","data":{"title":"쌓은 모양을 알아봐요(2)\n네 가지 표현","emoji":"🧩"},"suggested_extras":["v_l8_1"]},{"id":"s02","stage":"도입","block":"review","data":{"title":"지난 시간엔 무엇을 했나요?","content":"지난 시간에는 **위, 앞, 옆에서 본 모양**으로 쌓은 모양을 떠올렸어요. 오늘은 **수를 쓴 그림**과 **층별 그림**으로 쌓은 모양을 떠올리고 네 가지 표현을 견주어요.","items":[{"q":"교과서 44쪽 활동 1의 세 판으로 떠올린 모양은 쌓기나무가 몇 개일까요?","a":"8"},{"q":"앞과 옆에서 본 모양은 줄마다 무엇을 알려 줄까요?","a":"가장 높은 층"},{"q":"교과서 44쪽 문제 2에서 앞줄 가운데에 놓을 수 있는 쌓기나무 개수를 모두 말하면 무엇일까요?","a":"1개, 2개"}],"from":"u2_l07"},"suggested_extras":["q_l8_1"]},{"id":"s03","stage":"도입","block":"motivate","data":{"scene_title":"쌓기나무 설계 카드","desc":"친구들이 쌓기나무 설계 카드를 만들었어요. 어떤 카드에는 위에서 본 모양에 수가 쓰여 있고, 어떤 카드에는 1층·2층·3층 그림이 따로 있어요.","question":"어느 카드를 받으면 누가 쌓아도 똑같은 모양을 쌓을 수 있을까요? 위, 앞, 옆 세 판 카드와는 무엇이 다를까요?","img":"assets/photo/math/block_number_map_card.jpg","tnote":{"ask":["수를 쓴 카드로 쌓으면 모양이 하나로 정해질까요?","세 판 카드와 다른 점은?"],"watch":"네 표현을 같은 것으로 여기는 경우","min":3}},"suggested_extras":["q_l8_2","r_l8_1"]},{"id":"s04","stage":"전개","block":"concept","data":{"fig":{"k":"skp","h":[[3,2,0],[2,1,0],[1,2,1]],"show":["num","iso"]},"title":"수를 쓴 그림 → 쌓은 모양","content":"교과서 45쪽 활동 3 — **위에서 본 모양대로 1층을 쌓은 다음**, 1보다 큰 수가 쓰인 곳에 쌓기나무를 더 쌓아요.\n쓴 수를 모두 더하면 3 + 2 + 2 + 1 + 1 + 2 + 1 = **12개**예요.","tnote":{"ask":["1층에는 몇 개를 깔까요?","3을 쓴 자리에는 몇 개를 더 쌓나요?"],"watch":"가장 큰 수만큼 모든 자리에 쌓는 경우","min":4}},"suggested_extras":["e_l8_1"]},{"id":"s05","stage":"전개","block":"concept","data":{"fig":{"k":"skp","h":[[3,0,0],[3,2,1],[0,1,0]],"show":["layers","iso"]},"title":"층별 그림 → 쌓은 모양","content":"교과서 45쪽 활동 4 — **1층부터 층별로** 쌓은 모양을 떠올려요.\n1층 5개를 깔고, 그 위에 2층 3개, 3층 2개를 겹쳐 쌓아요 → **10개**.","tnote":{"ask":["2층은 어디 위에 놓이나요?","3층 칸은 2층 칸 안에 있나요?"],"watch":"층별 카드를 위층부터 쌓는 경우","min":4}},"suggested_extras":["t_l8_1"]},{"id":"s06","stage":"전개","block":"concept","data":{"fig":{"k":"skp","h":[[2,3,3],[0,2,0]],"show":["iso","num","front","side"]},"title":"네 가지 표현","content":"쌓은 모양은 ① **위, 앞, 옆에서 본 모양** ② **쌓은 모양과 위에서 본 모양** ③ **위에서 본 모양에 수를 쓴 것** ④ **층별로 나타낸 그림**으로 나타내요.\n③과 ④는 자리마다 개수를 알 수 있어 **하나로 정해지고**, ①은 가장 높은 층만 알려 주어 **여러 가지**일 수 있어요.","tnote":{"ask":["하나로 정해지는 표현은?","①은 왜 여러 가지일 수 있나요?"],"watch":"네 표현의 말뜻을 혼동하는 경우(지도서 165 유의 ④)","min":4}},"suggested_extras":["e_l8_2","t_l8_2"]},{"id":"s07","stage":"전개","block":"concept","data":{"fig":{"k":"tools","items":[{"name":"1층 모양"},{"name":"2층 — 라"},{"name":"3층 — 가 (2층 위에 겹치게)"}]},"title":"1층 위에 2층과 3층","content":"『수학익힘』 35쪽 — 1층 위에 2층과 3층을 서로 다른 모양으로 쌓으려면, **3층 쌓기나무는 1층과 2층에 놓인 쌓기나무 위에 겹치게** 놓아야 해요.\n2층에 라를 놓아야 3층에 가를 놓을 수 있어요.","tnote":{"ask":["2층에 가를 놓으면 3층에는 무엇을 놓을 수 있나요?","3층은 왜 2층 위여야 하나요?"],"watch":"위층 칸을 아래층 밖에 놓는 경우","min":4}},"suggested_extras":["q_l8_3"]},{"id":"s08","stage":"전개","block":"misconception","data":{"title":"이런 생각을 조심해요","label":"자주 하는 생각","wrong":"층별로 나타낸 그림이나 수를 쓴 그림도 위, 앞, 옆에서 본 모양처럼 **쌓은 모양이 여러 가지**로 나올 수 있다.","right":"수를 쓴 그림과 층별 그림은 **자리마다 쌓인 개수**를 알려 주어 쌓은 모양이 **하나로 정해져요**. 여러 가지가 나올 수 있는 것은 가장 높은 층만 알려 주는 **위, 앞, 옆에서 본 모양**이에요.","hint":"같은 수 쓴 그림으로 모둠 모두가 쌓아 견주어 보게 하세요.","tnote":{"ask":["모둠의 모양이 모두 같았나요?","세 판 카드로 쌓았을 때와 다른 점은?"],"watch":"네 표현을 모두 같은 성질로 여기는 경우","min":3}},"suggested_extras":["x_l8_1","x_l8_2"]},{"id":"s09","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ①","scenario":{"icon":"🧊","body":"교과서 45쪽 활동 3 — 위에서 본 모양에 수를 쓴 그림이에요."},"question":"똑같이 쌓을 때 필요한 쌓기나무는 몇 개일까요?","fig":{"k":"skp","h":[[3,2,0],[2,1,0],[1,2,1]],"show":["num"]},"input":"count_input","answer":12,"note":"풀이: 쓴 수를 모두 더해요 · 3 + 2 + 2 + 1 + 1 + 2 + 1 = 12 → **12**"},"suggested_extras":["t_l8_3"]},{"id":"s10","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ②","scenario":{"icon":"🧊","body":"교과서 45쪽 활동 4 — 층별로 나타낸 그림이에요."},"question":"똑같이 쌓을 때 필요한 쌓기나무는 몇 개일까요?","fig":{"k":"skp","h":[[3,0,0],[3,2,1],[0,1,0]],"show":["layers"]},"input":"count_input","answer":10,"note":"풀이: 1층 5개, 2층 3개, 3층 2개 · 5 + 3 + 2 = 10 → **10**"},"suggested_extras":["e_l8_3"]},{"id":"s11","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ③","scenario":{"icon":"🧊","body":"같은 수 쓴 그림(활동 3)으로 떠올린 쌓은 모양을 앞에서 보려고 해요."},"question":"앞에서 본 모양을 왼쪽부터 층으로 나타내면 무엇일까요?","fig":{"k":"skp","h":[[3,2,0],[2,1,0],[1,2,1]],"show":["num"],"ask":["front"]},"options":[{"text":"3층, 2층, 1층","correct":true},{"text":"2층, 2층, 3층"},{"text":"1층, 2층, 3층"},{"text":"6층, 5층, 1층"}],"note":"풀이: 줄마다 가장 큰 수를 찾아요 · 왼쪽 줄 3, 가운데 줄 2, 오른쪽 줄 1 → **3층, 2층, 1층**"},"suggested_extras":["q_l8_4"]},{"id":"s12","stage":"기본문제","block":"leveled_problem","data":{"title":"수준을 골라 풀어요","levels":{"기본":{"q":"위에서 본 모양에 수를 쓴 그림으로 쌓은 모양을 떠올릴 때 1층은 무엇대로 쌓을까요?","a":"위에서 본 모양","steps":["1층 모양 = 위에서 본 모양","그 위에 1보다 큰 수 자리에 더","위에서 본 모양"]},"도전":{"q":"교과서 45쪽 활동 3의 수 쓴 그림에서 2층에 놓인 쌓기나무는 몇 개일까요?","a":"4","steps":["2층 = 2 이상이 쓰인 자리","3, 2, 2, 2","4"]},"심화":{"q":"쌓은 모양을 친구에게 전화로만 알려 주어 똑같이 쌓게 하려면 네 가지 표현 가운데 어느 것으로 말하는 것이 좋을지 까닭과 함께 말해 봐요.","a":"여러 답 (예: 위에서 본 모양에 수를 쓴 것 — 줄마다 수만 불러 주면 하나로 정해진다)","open":true}},"tnote":{"ask":["기본에서 1층 모양은 무엇과 같나요?","심화에서 고른 표현은 하나로 정해지나요?"],"watch":"도전에서 2가 쓰인 자리만 세는 경우","min":5}},"suggested_extras":["q_l8_5","g_l8_1"]},{"id":"s13","stage":"응용문제","block":"offline_activity","data":{"title":"설계 카드 바꾸어 쌓기","type":"group","goal":"모둠이 같은 모양을 네 가지 표현 카드로 만든 뒤, 다른 모둠이 카드마다 쌓아 보며 하나로 정해지는지 견주기","steps":["모둠이 쌓기나무로 모양 하나를 쌓는다","세 판 · 수 쓴 그림 · 층별 그림 카드를 만든다","다른 모둠과 카드를 바꾸어 카드마다 쌓아 본다","처음 모양과 같은지, 다른 모양이 나온 카드는 무엇인지 발표한다"],"solo":["쌓기나무로 모양 하나를 쌓는다","세 판 · 수 쓴 그림 · 층별 그림을 모두 그린다","세 판으로 다른 모양도 쌓을 수 있는지 찾아 적는다"],"materials":["쌓기나무","모눈 카드","색연필"],"minutes":8,"tnote":{"ask":["어느 카드에서 다른 모양이 나왔나요?","수 쓴 카드로는 모두 같았나요?"],"watch":"카드를 서로 다른 모양으로 만든 모둠","min":8}},"suggested_extras":["g_l8_2","t_l8_4"]},{"id":"s14","stage":"응용문제","block":"real_world","data":{"title":"건물 높이 지도","scenario":{"icon":"🗾","body":"도시 지도 앱의 입체 지도는 건물마다 층수(높이) 정보를 가지고 있어 위에서 본 지도만으로도 입체 건물을 그려 내요."},"content":"**수를 쓴 그림**과 **층별 그림**은 자리마다 개수를 알려 주어 쌓은 모양이 하나로 정해져요. **위, 앞, 옆에서 본 모양**은 여러 가지일 수 있어요."},"suggested_extras":["r_l8_2","r_l8_3"]},{"id":"s15","stage":"응용문제","block":"advanced_problem","data":{"title":"생각을 넓혀요","context":"『수학익힘』 35쪽 — 1층 모양 위에 2층과 3층을 서로 다른 모양으로 쌓으려 해요. 보기 가, 나, 다, 라 가운데 2층에 가, 나, 다를 놓으면 3층에 놓을 모양이 없고, 라를 놓으면 3층에 가를 놓을 수 있어요.","challenge":"2층과 3층에 놓을 모양을 고르고 그 까닭을 말해 볼까요?","note":"풀이: 3층 쌓기나무는 1층과 2층에 놓인 쌓기나무 위에 겹치게 놓아야 해요 · 2층에 라를 놓으면 그 위에 가가 겹쳐 놓여요 · **2층 라, 3층 가**","tnote":{"ask":["3층 칸은 어디 안에 있어야 하나요?","2층에 가를 놓으면 왜 안 될까요?"],"watch":"3층을 1층 위에 바로 놓는 경우","min":4}},"suggested_extras":["t_l8_5"]},{"id":"s16","stage":"정리","block":"exit_ticket","data":{"title":"오늘 확인해요","items":[{"q":"교과서 45쪽 활동 3은 쌓기나무가 몇 개일까요?","a":"12"},{"q":"층별로 나타낸 그림은 쌓은 모양이 하나로 정해질까요?","a":"예"},{"q":"네 가지 표현 가운데 쌓은 모양이 여러 가지일 수 있는 것은 무엇일까요?","a":"위, 앞, 옆에서 본 모양"}],"self":["오늘 배운 것을 혼자 설명할 수 있어요","조금 헷갈려요","다시 배우고 싶어요"]},"suggested_extras":[]},{"id":"s17","stage":"정리","block":"summary","data":{"title":"오늘 배운 것","points":["수를 쓴 그림 — 위에서 본 모양대로 1층, 1보다 큰 수 자리에 더 쌓기.","층별 그림 — 1층부터 층별로 겹쳐 쌓기.","수를 쓴 그림·층별 그림은 하나로 정해지고, 위·앞·옆은 여러 가지일 수 있어요.","설계 카드 가운데 누구나 같은 모양을 쌓는 카드를 찾았다."],"arrows":["수 쓴 그림","층별 그림","네 표현 견주기"]},"suggested_extras":["r_l8_1"]},{"id":"s18","stage":"정리","block":"self_assessment","data":{"title":"스스로 점검해요","items":["📚 지식·이해 — 네 가지 표현의 차이를 말할 수 있나요?","🔧 과정·기능 — 수 쓴 그림·층별 그림으로 쌓을 수 있나요?","💛 가치·태도 — 표현을 바꾸어 나타내 보려 했나요?"],"prompts":["네 표현 가운데 가장 좋아하는 표현과 까닭은?"]},"suggested_extras":["e_l8_3"]},{"id":"s19","stage":"정리","block":"next_lesson","data":{"title":"다음 시간엔","preview":"쌓기나무 3개로 만들 수 있는 서로 다른 모양은 두 가지뿐이에요. 4개로는 몇 가지를 만들 수 있을까요?","emoji":"🤖"},"suggested_extras":["c_l8_1"]}],"extras":[{"id":"v_l8_1","type":"video","icon":"🎥","title":"수 쓴 그림과 층별 그림","url":"https://www.youtube.com/results?search_query=%EC%B4%88%EB%93%B1+6%ED%95%99%EB%85%84+%EC%88%98%EB%A5%BC+%EC%93%B4+%EA%B7%B8%EB%A6%BC+%EC%B8%B5%EB%B3%84+%EA%B7%B8%EB%A6%BC+%EB%B3%B4%EA%B3%A0+%EC%8C%93%EC%9D%80+%EB%AA%A8%EC%96%91","description":"네 가지 표현.","source":"유튜브 검색 (교사 사전 확인 권장)","fit_slides":["concept","motivate"]},{"id":"q_l8_1","type":"fun_question","icon":"💡","title":"1층","content":"수 쓴 그림에서 1층은 무엇대로 쌓을까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l8_2","type":"fun_question","icon":"💡","title":"층별 차례","content":"층별 그림은 어느 층부터 쌓을까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l8_3","type":"fun_question","icon":"💡","title":"하나로","content":"수 쓴 그림으로 쌓으면 모두 같은 모양일까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l8_4","type":"fun_question","icon":"💡","title":"여러 가지","content":"여러 가지 모양이 나올 수 있는 표현은?","fit_slides":["concept","basic_problem"]},{"id":"q_l8_5","type":"fun_question","icon":"💡","title":"3층 자리","content":"3층은 어디에 놓일까요?","fit_slides":["concept","basic_problem"]},{"id":"t_l8_1","type":"tip","icon":"🧩","title":"말뜻","content":"네 표현의 말뜻을 구체적으로 이해하게 하세요(지도서 165 유의 ④).","fit_slides":["concept","misconception"]},{"id":"t_l8_2","type":"tip","icon":"🧩","title":"두 방법 경험","content":"실물과 컴퓨터로 모두 확인하게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l8_3","type":"tip","icon":"🧩","title":"친구와 견주기","content":"친구가 쌓은 모양과 비교하게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l8_4","type":"tip","icon":"🧩","title":"겹치게","content":"위층은 아래층 위에 겹친다는 것을 손으로 보여 주세요.","fit_slides":["concept","misconception"]},{"id":"t_l8_5","type":"tip","icon":"🧩","title":"빼기 놀이","content":"세 판이 변하지 않게 쌓기나무 빼기 놀이를 소개하세요.","fit_slides":["concept","misconception"]},{"id":"r_l8_1","type":"real_world","icon":"🌍","title":"입체 지도","content":"층수 정보로 건물 그리기.","fit_slides":["real_world","summary"]},{"id":"r_l8_2","type":"real_world","icon":"🌍","title":"아파트 분양도","content":"동별 층수.","fit_slides":["real_world","summary"]},{"id":"r_l8_3","type":"real_world","icon":"🌍","title":"블록 설계도","content":"층별 조립 그림.","fit_slides":["real_world","summary"]},{"id":"g_l8_1","type":"game","icon":"🎮","title":"빼기 놀이","content":"세 판이 그대로이게 쌓기나무 빼기.","fit_slides":["leveled_problem","offline_activity"]},{"id":"g_l8_2","type":"game","icon":"🎮","title":"카드 바꾸기","content":"네 표현 카드 바꾸어 쌓기.","fit_slides":["leveled_problem","offline_activity"]},{"id":"x_l8_1","type":"misconception","icon":"⚠️","title":"모두 여러 가지","content":"수 쓴 그림도 여러 가지라고 여기기.","fit_slides":["misconception","basic_problem"]},{"id":"x_l8_2","type":"misconception","icon":"⚠️","title":"위층 밖","content":"위층을 아래층 밖에 놓기.","fit_slides":["misconception","basic_problem"]},{"id":"e_l8_1","type":"example","icon":"📝","title":"활동 3","content":"수 쓴 그림과 쌓은 모양을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l8_2","type":"example","icon":"📝","title":"활동 4","content":"층별 그림과 쌓은 모양을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l8_3","type":"example","icon":"📝","title":"네 표현 판","content":"네 가지 표현 카드를 나란히 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"c_l8_1","type":"checklist","icon":"✅","title":"다음 시간 준비","content":"쌓기나무 4개와 색연필을 챙깁니다.","fit_slides":["next_lesson"]}]};
  window.LESSONS["u2_l09"] = {"meta":{"grade":6,"subject":"수학","term":2,"unit":2,"unit_title":"공간과 입체","n":9,"title":"여러 가지 모양을 만들어요","std":"[6수03-10] 쌓기나무로 만든 입체도형의 위, 앞, 옆에서 본 모양을 표현할 수 있고, 이러한 표현을 보고 입체도형의 모양을 추측할 수 있다.","duration_min":40,"lesson_format":"개념 차시 · 2세대 19장(7요소)","theme":"여러 방향에서 보는 공간","source":"2022 개정 수학 6-2 지도서 2단원(163~208쪽 · 『수학』 31~54 · 『수학익힘』 25~40) — 자기주도 원문 없이 지도서에서 세움 · 투영 회수 키 grade6/semester2/math/2단원_공간과입체/g6_math_u2_l09_여러가지모양을만들어요.html","src_key":"u2_l09"},"slides":[{"id":"s01","stage":"도입","block":"cover","data":{"title":"여러 가지 모양을 만들어요\n쌓기나무 4개로","emoji":"🤖"},"suggested_extras":["v_l9_1"]},{"id":"s02","stage":"도입","block":"review","data":{"title":"지난 시간엔 무엇을 했나요?","content":"지난 시간에는 **수를 쓴 그림**과 **층별 그림**으로 쌓은 모양을 떠올렸어요. 오늘은 조건에 맞게 **여러 가지 모양**을 만들어요.","items":[{"q":"교과서 45쪽 활동 3은 쌓기나무가 몇 개일까요?","a":"12"},{"q":"층별로 나타낸 그림은 쌓은 모양이 하나로 정해질까요?","a":"예"},{"q":"네 가지 표현 가운데 쌓은 모양이 여러 가지일 수 있는 것은 무엇일까요?","a":"위, 앞, 옆에서 본 모양"}],"from":"u2_l08"},"suggested_extras":["q_l9_1"]},{"id":"s03","stage":"도입","block":"motivate","data":{"scene_title":"로봇 공장의 쌓기나무","desc":"로봇 공장에서 쌓기나무를 붙여 모양을 만들어요. 쌓기나무 3개로 만든 서로 다른 모양은 두 가지뿐이래요. 돌리거나 뒤집었을 때 모양이 같은 것은 하나로 생각해요.","question":"쌓기나무를 1개 더 붙여 4개로 만들면 서로 다른 모양은 몇 가지일까요?","img":"assets/photo/math/robot_conveyor_blocks.jpg","tnote":{"ask":["3개로 만든 두 모양은 무엇인가요?","돌려서 같으면 몇 가지로 셀까요?"],"watch":"놓인 방향이 다르면 다른 모양이라고 여기는 경우","min":3}},"suggested_extras":["q_l9_2","r_l9_1"]},{"id":"s04","stage":"전개","block":"concept","data":{"fig":{"k":"u6r","items":[{"k":"skp","h":[[1,1,1]],"show":["iso"],"cap":"일자"},{"k":"skp","h":[[1,0],[1,1]],"show":["iso"],"cap":"ㄱ자"}]},"title":"쌓기나무 3개로 만든 두 가지","content":"쌓기나무 3개로 만들 수 있는 서로 다른 모양은 **일자 모양**과 **ㄱ자 모양** 두 가지예요.\n**돌리거나 뒤집었을 때 모양이 같은 것은 하나의 모양**으로 생각해요.","tnote":{"ask":["ㄱ자 모양을 돌리면 다른 모양이 될까요?","두 가지뿐인 까닭은?"],"watch":"돌린 모양을 새 모양으로 세는 경우","min":4}},"suggested_extras":["e_l9_1"]},{"id":"s05","stage":"전개","block":"concept","data":{"fig":{"k":"u6r","items":[{"k":"skp","h":[[1,1,1,1]],"show":["iso"]},{"k":"skp","h":[[1,0,0],[1,1,1]],"show":["iso"]},{"k":"skp","h":[[0,1,0],[1,1,1]],"show":["iso"]},{"k":"skp","h":[[1,1],[1,1]],"show":["iso"]}]},"title":"1개 더 붙여 4개로","content":"일자 모양과 ㄱ자 모양에 쌓기나무를 **1개씩 더 붙여** 모양을 만들어요.\n만든 모양을 돌리거나 뒤집어 같은 것을 빼면 쌓기나무 4개로 만들 수 있는 서로 다른 모양은 **모두 8가지**예요.","tnote":{"ask":["같은 모양이 된 것을 찾았나요?","빠뜨린 모양은 없을까요?"],"watch":"같은 모양을 두 번 세는 경우","min":4}},"suggested_extras":["t_l9_1"]},{"id":"s06","stage":"전개","block":"concept","data":{"fig":{"k":"tools","items":[{"name":"쌓기나무 붙인 한 덩어리"},{"name":"돌리기"},{"name":"뒤집기 — 바닥에서 떠도 같은 모양"}]},"title":"돌리거나 뒤집을 때","content":"쌓기나무는 원래 떨어지고 모두 바닥에 닿아야 하는 교구예요.\n하지만 모양을 **돌리거나 뒤집어** 볼 때는 쌓기나무가 **서로 붙어 있다고 보고** 바닥에 닿지 않는 상태로 돌려 봐요.","tnote":{"ask":["뒤집으면 바닥에서 뜨는 쌓기나무가 생기나요?","그래도 같은 모양인가요?"],"watch":"바닥에서 뜨는 모양은 만들 수 없다고 여기는 경우(지도서 166 유의 ⑧)","min":4}},"suggested_extras":["e_l9_2","t_l9_2"]},{"id":"s07","stage":"전개","block":"concept","data":{"fig":{"k":"u6r","items":[{"k":"skp","h":[[1,1]],"show":["iso"],"cap":"보라색 2개"},{"k":"skp","h":[[1,0],[1,1]],"show":["iso"],"cap":"초록색 3개"}]},"title":"두 모양을 합쳐 새 모양","content":"보라색 쌓기나무 2개 모양과 초록색 쌓기나무 3개 모양을 **합쳐** 새로운 모양을 만들어요.\n같은 새 모양을 여러 방법으로 만들 수 있고, 어떻게 만들었는지 **보라색과 초록색으로 구분**해 칠해요.\n변하지 않는 것은 **모양을 만든 두 가지 모양**이에요.","tnote":{"ask":["합친 모양은 쌓기나무 몇 개인가요?","변하는 것과 변하지 않는 것은?"],"watch":"두 모양을 한 색으로 다 칠하는 경우","min":4}},"suggested_extras":["q_l9_3"]},{"id":"s08","stage":"전개","block":"misconception","data":{"title":"이런 생각을 조심해요","label":"자주 하는 생각","wrong":"돌리거나 뒤집어 **완전히 겹쳐지더라도** 놓인 방향이 다르면 다른 모양이다.","right":"돌리거나 뒤집었을 때 모양이 같은 것은 **하나의 모양**으로 생각해요. 그래서 쌓기나무 3개로는 **2가지**, 4개로는 **8가지**예요.","hint":"쌓기나무를 서로 붙이거나 끼우는 모형으로 같은 모양을 만들어 직접 돌려 보게 하세요(지도서 199).","tnote":{"ask":["두 모양을 겹쳐 볼 수 있나요?","그러면 몇 가지로 세나요?"],"watch":"방향만 다른 모양을 따로 세는 경우","min":3}},"suggested_extras":["x_l9_1","x_l9_2"]},{"id":"s09","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ①","scenario":{"icon":"🧊","body":"쌓기나무 3개로 모양을 만들어요. 돌리거나 뒤집었을 때 같은 모양은 하나로 생각해요."},"question":"쌓기나무 3개로 만들 수 있는 서로 다른 모양은 몇 가지일까요?","fig":{"k":"u6r","items":[{"k":"skp","h":[[1,1,1]],"show":["iso"]},{"k":"skp","h":[[1,0],[1,1]],"show":["iso"]}]},"input":"count_input","answer":2,"note":"풀이: 일자 모양과 ㄱ자 모양 · 2가지 → **2**"},"suggested_extras":["t_l9_3"]},{"id":"s10","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ②","scenario":{"icon":"🧊","body":"두 가지 모양에 쌓기나무를 1개씩 더 붙여 만들었어요."},"question":"쌓기나무 4개로 만들 수 있는 서로 다른 모양은 몇 가지일까요?","fig":{"k":"u6r","items":[{"k":"skp","h":[[1,1,1,1]],"show":["iso"]},{"k":"skp","h":[[1,1],[1,1]],"show":["iso"]}]},"input":"count_input","answer":8,"note":"풀이: 1개씩 붙일 수 있는 자리마다 붙여요 · 같은 모양을 빼면 8가지 → **8**"},"suggested_extras":["e_l9_3"]},{"id":"s11","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ③","scenario":{"icon":"🧊","body":"『수학익힘』 37쪽 — 우진이가 벽돌 두 개를 골라 정육면체 모양 건축물 모형을 만들었어요. 두 벽돌은 각각 쌓기나무 4개로 만든 모양이에요."},"question":"정육면체 모형은 쌓기나무 몇 개로 쌓은 모양일까요?","fig":{"k":"skp","h":[[1,1],[1,1]],"show":["iso"],"cap":"벽돌 하나 = 쌓기나무 4개"},"options":[{"text":"4개"},{"text":"6개"},{"text":"8개","correct":true},{"text":"12개"}],"note":"풀이: 4 + 4 = 8 · 가로·세로·높이 2개씩 2 × 2 × 2 = 8 → **8개**"},"suggested_extras":["q_l9_4"]},{"id":"s12","stage":"기본문제","block":"leveled_problem","data":{"title":"수준을 골라 풀어요","levels":{"기본":{"q":"보라색 쌓기나무 2개 모양과 초록색 쌓기나무 3개 모양을 합친 모양은 쌓기나무 몇 개일까요?","a":"5","steps":["보라색 2개","초록색 3개","2 + 3 = 5"]},"도전":{"q":"소마 큐브는 쌓기나무 3개짜리 1조각과 4개짜리 6조각이에요. 7조각으로 만든 큰 정육면체는 쌓기나무 몇 개일까요?","a":"27","steps":["4개짜리 6조각 = 24개","3 + 24 = 27","3 × 3 × 3 = 27"]},"심화":{"q":"짝과 각자 쌓기나무 3개로 모양을 만들어 합쳤을 때 만들 수 있는 새 모양을 두 가지 이상 생각해 말해 봐요.","a":"여러 답 (예: 일자 + 일자 → 2줄 직육면체 · ㄱ자 + ㄱ자 → 계단 모양)","open":true}},"tnote":{"ask":["기본에서 두 모양의 개수를 어떻게 했나요?","심화에서 만든 모양은 6개인가요?"],"watch":"도전에서 3 × 7 = 21로 셈하는 경우","min":5}},"suggested_extras":["q_l9_5","g_l9_1"]},{"id":"s13","stage":"응용문제","block":"offline_activity","data":{"title":"너와 내가 합쳐 새로운 모양 만들기","type":"pair","goal":"짝과 각자 쌓기나무 3개로 만든 모양을 합쳐 새 모양을 만들고, 모둠 친구들과 다시 합쳐 관찰하기","steps":["각자 쌓기나무 3개로 만들고 싶은 모양을 만든다","짝과 합쳐 새로운 모양을 만든다","어떻게 합쳤는지 두 색으로 구분해 그린다","모둠 친구들과 합쳐 더 큰 모양을 만들고 관찰한다"],"solo":["쌓기나무 3개로 모양 두 개를 만든다","두 모양을 합쳐 새 모양을 세 가지 만든다","새 모양마다 어떻게 합쳤는지 두 색으로 칠해 그린다"],"materials":["쌓기나무","색연필(보라·초록)","기록지"],"minutes":8,"tnote":{"ask":["같은 새 모양을 다른 방법으로도 만들었나요?","두 색으로 구분했나요?"],"watch":"합친 뒤 처음 두 모양을 못 찾는 짝","min":8}},"suggested_extras":["g_l9_2","t_l9_4"]},{"id":"s14","stage":"응용문제","block":"real_world","data":{"title":"소마 큐브 퍼즐","scenario":{"icon":"🧊","body":"소마 큐브는 쌓기나무 3개로 만든 조각 1개와 4개로 만든 조각 6개, 모두 7조각이에요. 잘 맞추면 3 + 4 × 6 = 27개짜리 큰 정육면체가 돼요."},"content":"벽돌의 모양이 다양하면 건축물의 모양을 다양하게 만들 수 있어요. 쌓기나무 몇 개를 붙인 모양들을 **합치면** 여러 가지 새 모양을 만들 수 있어요."},"suggested_extras":["r_l9_2","r_l9_3"]},{"id":"s15","stage":"응용문제","block":"advanced_problem","data":{"title":"생각을 넓혀요","context":"『수학익힘』 37쪽 — 우진이는 여러 가지 벽돌 가, 나, 다, 라, 마, 바 가운데 두 개를 골라 정육면체 모양의 건축물 모형을 만들었어요. 우진이가 고른 벽돌은 가와 라예요.","challenge":"가와 라로 정육면체를 만들 수 있는 까닭을 쌓기나무 개수로 말해 볼까요?","note":"풀이: 정육면체 모형은 쌓기나무 8개 · 가 4개 + 라 4개 = 8 · 라를 돌리거나 뒤집어 가와 합치면 2 × 2 × 2 정육면체 · **가, 라**","tnote":{"ask":["정육면체는 쌓기나무 몇 개인가요?","라를 어떻게 돌려 합치나요?"],"watch":"개수만 맞으면 된다고 여기는 경우","min":4}},"suggested_extras":["t_l9_5"]},{"id":"s16","stage":"정리","block":"exit_ticket","data":{"title":"오늘 확인해요","items":[{"q":"쌓기나무 3개로 만들 수 있는 서로 다른 모양은 몇 가지일까요?","a":"2"},{"q":"쌓기나무 4개로 만들 수 있는 서로 다른 모양은 몇 가지일까요?","a":"8"},{"q":"돌리거나 뒤집었을 때 모양이 같으면 몇 가지로 셀까요?","a":"하나"}],"self":["오늘 배운 것을 혼자 설명할 수 있어요","조금 헷갈려요","다시 배우고 싶어요"]},"suggested_extras":[]},{"id":"s17","stage":"정리","block":"summary","data":{"title":"오늘 배운 것","points":["돌리거나 뒤집어 같은 모양은 하나로 세요.","쌓기나무 3개로 2가지, 4개로 8가지 모양을 만들어요.","두 모양을 합쳐 새 모양을 만들고, 두 색으로 구분해요.","로봇 공장의 쌓기나무로 같은 모양과 다른 모양을 가려냈다."],"arrows":["3개 → 2가지","1개씩 붙이기","4개 → 8가지"]},"suggested_extras":["r_l9_1"]},{"id":"s18","stage":"정리","block":"self_assessment","data":{"title":"스스로 점검해요","items":["📚 지식·이해 — 같은 모양을 가려내는 기준을 말할 수 있나요?","🔧 과정·기능 — 조건에 맞게 여러 가지 모양을 만들 수 있나요?","💛 가치·태도 — 빠뜨린 모양이 없는지 끝까지 찾아보려 했나요?"],"prompts":["오늘 만든 모양 가운데 가장 마음에 드는 모양은?"]},"suggested_extras":["e_l9_3"]},{"id":"s19","stage":"정리","block":"next_lesson","data":{"title":"다음 시간엔","preview":"공학 도구 「알지오매스 키즈」로 쌓기나무를 쌓아 만들고 싶은 건물을 만들어요. 화면 속 건물을 여러 방향에서 볼 수 있을까요?","emoji":"🏙️"},"suggested_extras":["c_l9_1"]}],"extras":[{"id":"v_l9_1","type":"video","icon":"🎥","title":"여러 가지 모양","url":"https://www.youtube.com/results?search_query=%EC%B4%88%EB%93%B1+6%ED%95%99%EB%85%84+%EC%8C%93%EA%B8%B0%EB%82%98%EB%AC%B4+4%EA%B0%9C%EB%A1%9C+%EB%A7%8C%EB%93%A4+%EC%88%98+%EC%9E%88%EB%8A%94+%EB%AA%A8%EC%96%91","description":"돌리고 뒤집어 같은 모양 찾기.","source":"유튜브 검색 (교사 사전 확인 권장)","fit_slides":["concept","motivate"]},{"id":"q_l9_1","type":"fun_question","icon":"💡","title":"3개","content":"3개로 만든 모양은 몇 가지일까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l9_2","type":"fun_question","icon":"💡","title":"4개","content":"4개로는 몇 가지일까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l9_3","type":"fun_question","icon":"💡","title":"같은 모양","content":"돌려서 같으면 같은 모양일까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l9_4","type":"fun_question","icon":"💡","title":"뒤집기","content":"뒤집으면 바닥에서 떠도 될까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l9_5","type":"fun_question","icon":"💡","title":"합치기","content":"두 모양을 합치면 몇 개일까요?","fit_slides":["concept","basic_problem"]},{"id":"t_l9_1","type":"tip","icon":"🧩","title":"끼우는 모형","content":"돌리기가 어려우면 끼우는 모형을 붙여 직접 돌려 보게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l9_2","type":"tip","icon":"🧩","title":"두 활동 구분","content":"ㄱ은 같은 모양 여러 방법, ㄴ은 합쳐 여러 모양임에 유의하세요(지도서 200).","fit_slides":["concept","misconception"]},{"id":"t_l9_3","type":"tip","icon":"🧩","title":"색칠","content":"어떻게 만들었는지 보라·초록으로 구분해 칠하게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l9_4","type":"tip","icon":"🧩","title":"한 모양 먼저","content":"한 모양의 자리를 먼저 찾고 나머지를 확인하게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l9_5","type":"tip","icon":"🧩","title":"소마 큐브","content":"읽기 자료로 소마 큐브를 소개하세요.","fit_slides":["concept","misconception"]},{"id":"r_l9_1","type":"real_world","icon":"🌍","title":"건물 만들기","content":"알지오매스 키즈 27개 건물.","fit_slides":["real_world","summary"]},{"id":"r_l9_2","type":"real_world","icon":"🌍","title":"벽돌 건축","content":"다양한 벽돌 모양.","fit_slides":["real_world","summary"]},{"id":"r_l9_3","type":"real_world","icon":"🌍","title":"테트리스","content":"4칸 조각 7가지.","fit_slides":["real_world","summary"]},{"id":"g_l9_1","type":"game","icon":"🎮","title":"소마 큐브","content":"7조각으로 정육면체 맞추기.","fit_slides":["leveled_problem","offline_activity"]},{"id":"g_l9_2","type":"game","icon":"🎮","title":"같은 모양 찾기","content":"돌려서 같은 조각 짝 찾기.","fit_slides":["leveled_problem","offline_activity"]},{"id":"x_l9_1","type":"misconception","icon":"⚠️","title":"방향이 다르면","content":"방향만 다른 모양을 따로 세기.","fit_slides":["misconception","basic_problem"]},{"id":"x_l9_2","type":"misconception","icon":"⚠️","title":"뜨면 안 돼","content":"뒤집으면 만들 수 없다고 여기기.","fit_slides":["misconception","basic_problem"]},{"id":"e_l9_1","type":"example","icon":"📝","title":"3개 두 모양","content":"일자·ㄱ자 모양을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l9_2","type":"example","icon":"📝","title":"4개 8가지","content":"8가지 모양 카드를 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l9_3","type":"example","icon":"📝","title":"합치기","content":"보라·초록으로 칠한 합친 모양을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"c_l9_1","type":"checklist","icon":"✅","title":"다음 시간 준비","content":"쌓기나무 10개를 챙깁니다.","fit_slides":["next_lesson"]}]};
  window.LESSONS["u2_l10"] = {"meta":{"grade":6,"subject":"수학","term":2,"unit":2,"unit_title":"공간과 입체","n":10,"title":"차곡차곡 건물 만들기 (함께하는 수학)","std":"[6수03-10] 쌓기나무로 만든 입체도형의 위, 앞, 옆에서 본 모양을 표현할 수 있고, 이러한 표현을 보고 입체도형의 모양을 추측할 수 있다.","duration_min":40,"lesson_format":"함께하는 수학 · 2세대 19장(7요소)","theme":"여러 방향에서 보는 공간","source":"2022 개정 수학 6-2 지도서 2단원(163~208쪽 · 『수학』 31~54 · 『수학익힘』 25~40) — 자기주도 원문 없이 지도서에서 세움 · 자기주도 원문 없는 차시(함께하는 수학)","src_key":"u2_l10"},"slides":[{"id":"s01","stage":"도입","block":"cover","data":{"title":"차곡차곡 건물 만들기\n공학 도구로 쌓기나무 쌓기","emoji":"🏙️"},"suggested_extras":["v_l10_1"]},{"id":"s02","stage":"도입","block":"review","data":{"title":"지난 시간엔 무엇을 했나요?","content":"지난 시간에는 조건에 맞게 **여러 가지 모양**을 만들었어요. 오늘은 공학 도구 「알지오매스 키즈」로 쌓기나무를 쌓아 **만들고 싶은 건물**을 만들고, 위, 앞, 옆에서 본 모양으로 소개해요.","items":[{"q":"쌓기나무 3개로 만들 수 있는 서로 다른 모양은 몇 가지일까요?","a":"2"},{"q":"쌓기나무 4개로 만들 수 있는 서로 다른 모양은 몇 가지일까요?","a":"8"},{"q":"돌리거나 뒤집었을 때 모양이 같으면 몇 가지로 셀까요?","a":"하나"}],"from":"u2_l09"},"suggested_extras":["q_l10_1"]},{"id":"s03","stage":"도입","block":"motivate","data":{"scene_title":"화면 속 쌓기나무 건물","desc":"「알지오매스 키즈」(algeomath.kr/kids)에 들어가 쌓기나무 도구를 고르면 화면 위에 쌓기나무를 쌓을 수 있어요. 앞쪽·뒤쪽·왼쪽·오른쪽·위쪽·아래쪽 버튼을 누르면 쌓은 모양을 여러 방향에서 볼 수 있어요.","question":"내가 만들고 싶은 건물을 쌓기나무로 쌓으면 위, 앞, 옆에서 본 모양은 어떨까요? 실제 쌓기나무로 쌓을 때와 무엇이 다를까요?","img":"assets/photo/math/algeomath_block_building.jpg","tnote":{"ask":["어떤 건물을 만들고 싶나요?","방향 버튼으로 무엇을 볼 수 있나요?"],"watch":"도구를 다루는 데만 시간을 쓰는 경우(지도서 203 — 능숙함보다 나타내기에 초점)","min":3}},"suggested_extras":["q_l10_2","r_l10_1"]},{"id":"s04","stage":"전개","block":"concept","data":{"fig":{"k":"tools","items":[{"name":"쌓기나무 도구 → 쌓을 곳 선택"},{"name":"지우기 도구 → 지울 쌓기나무 선택"},{"name":"쌓기나무가 쌓여요"}]},"title":"쌓기나무를 쌓는 방법","content":"쌓기나무 도구를 고른 다음 **쌓고 싶은 곳을 선택하면** 쌓기나무를 쌓을 수 있어요.\n지우기 도구를 고른 다음 쌓기나무를 선택하면 **쌓기나무를 지울 수** 있어요.\n먼저 도구를 충분히 익힌 다음 건물을 만들어요.","tnote":{"ask":["쌓기나무를 하나 쌓아 볼까요?","잘못 쌓은 것은 어떻게 지우나요?"],"watch":"도구 이름만 외우고 쌓아 보지 않는 경우","min":4}},"suggested_extras":["e_l10_1"]},{"id":"s05","stage":"전개","block":"concept","data":{"fig":{"k":"skp","h":[[0,1,0],[1,2,3],[0,1,0]],"show":["iso","top","front","side"]},"title":"여러 방향에서 보기","content":"**앞쪽·뒤쪽·왼쪽·오른쪽·위쪽·아래쪽** 버튼을 선택하면 쌓은 모양을 여러 방향에서 볼 수 있어요.\n위쪽을 누르면 위에서 본 모양, 앞쪽을 누르면 앞에서 본 모양, 오른쪽을 누르면 옆에서 본 모양이 보여요.\n실제 쌓기나무로는 보기 어려운 **뒤와 밑**에서 본 모양도 쉽게 볼 수 있어요.","tnote":{"ask":["위쪽 버튼으로 본 모양은 무엇과 같나요?","오른쪽 버튼은 어느 판과 같나요?"],"watch":"왼쪽 버튼으로 본 모양을 옆에서 본 모양으로 여기는 경우","min":4}},"suggested_extras":["t_l10_1"]},{"id":"s06","stage":"전개","block":"concept","data":{"fig":{"k":"tools","items":[{"name":"1층 14개"},{"name":"2층 7개"},{"name":"3층 6개"},{"name":"→ 모두 27개"}]},"title":"건물을 쌓아 소개하기","content":"교과서 예 — 1층에 **14개**, 2층에 **7개**, 3층에 **6개**를 쌓아 건물을 만들었어요.\n14 + 7 + 6 = **27개**의 쌓기나무로 만든 건물이에요.\n친구에게 소개할 때는 층마다 쌓은 개수와 **위, 앞, 옆에서 본 모양**을 함께 말해요.","tnote":{"ask":["층마다 몇 개씩인가요?","모두 몇 개로 만들었나요?"],"watch":"층 수(3)를 개수로 말하는 경우","min":4}},"suggested_extras":["e_l10_2","t_l10_2"]},{"id":"s07","stage":"전개","block":"concept","data":{"fig":{"k":"u6r","items":[{"k":"skp","h":[[1,2,3,1],[1,0,0,1]],"show":["iso"],"cap":"41쪽 문제 3 · 9개"},{"k":"skp","h":[[3,2,1],[2,0,0],[1,0,0]],"show":["iso"],"cap":"42쪽 문제 4 · 9개"}]},"title":"같은 개수, 다른 모양","content":"활동을 바꾸어 — 모둠 친구들과 **사용할 쌓기나무 개수를 정하고** 각자 모양을 쌓아 견주어요.\n같은 개수로 쌓아도 모양은 서로 다를 수 있어요. 교과서 41쪽 문제 3과 42쪽 문제 4는 모두 **9개**지만 모양이 달라요.","tnote":{"ask":["두 모양은 개수가 같나요?","모양은 어떻게 다른가요?"],"watch":"개수가 같으면 모양도 같다고 여기는 경우","min":4}},"suggested_extras":["q_l10_3"]},{"id":"s08","stage":"전개","block":"misconception","data":{"title":"이런 생각을 조심해요","label":"자주 하는 생각","wrong":"공학 도구에서 **왼쪽** 버튼을 눌러 본 모양이 교과서의 「옆에서 본 모양」이다.","right":"교과서의 옆에서 본 모양은 **오른쪽에서 본 모양**이에요. 왼쪽에서 본 모양은 오른쪽에서 본 모양을 **뒤집은** 모양이라 서로 달라요.","hint":"오른쪽 버튼과 왼쪽 버튼을 번갈아 눌러 두 모양을 견주어 보게 하세요.","tnote":{"ask":["오른쪽과 왼쪽에서 본 모양은 어떤 관계인가요?","교과서 옆은 어느 쪽인가요?"],"watch":"두 버튼 모양을 같다고 여기는 경우","min":3}},"suggested_extras":["x_l10_1","x_l10_2"]},{"id":"s09","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ①","scenario":{"icon":"🧊","body":"「알지오매스 키즈」로 1층에 14개, 2층에 7개, 3층에 6개를 쌓아 건물을 만들었어요."},"question":"건물을 만든 쌓기나무는 모두 몇 개일까요?","fig":{"k":"tools","items":[{"name":"1층 14개"},{"name":"2층 7개"},{"name":"3층 6개"}]},"input":"count_input","answer":27,"note":"풀이: 층마다 쌓은 개수를 더해요 · 14 + 7 + 6 = 27 → **27**"},"suggested_extras":["t_l10_3"]},{"id":"s10","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ②","scenario":{"icon":"🧊","body":"쌓은 모양을 보며 방향 버튼을 눌러요."},"question":"위쪽 버튼을 누르면 어떤 모양을 볼 수 있을까요?","fig":{"k":"skp","h":[[0,1,0],[1,2,3],[0,1,0]],"show":["iso"]},"options":[{"text":"앞에서 본 모양"},{"text":"위에서 본 모양","correct":true},{"text":"옆에서 본 모양"},{"text":"아래에서 본 모양"}],"note":"풀이: 위쪽에서 내려다보아요 · 위에서 본 모양 = 1층 모양 → **위에서 본 모양**"},"suggested_extras":["e_l10_3"]},{"id":"s11","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ③","scenario":{"icon":"🧊","body":"모둠이 쌓기나무 10개로 정해 쌓은 모양(교과서 41쪽 모양)을 층별로 확인했어요. 3층 화면이 가려졌어요."},"question":"3층에 놓인 쌓기나무는 몇 개일까요?","fig":{"k":"skp","h":[[2,3,0],[1,2,1],[1,0,0]],"show":["layers"],"qlayer":3},"input":"count_input","answer":1,"note":"풀이: 1층 6개, 2층 3개 · 10 − 6 − 3 = 1 → **1**"},"suggested_extras":["q_l10_4"]},{"id":"s12","stage":"기본문제","block":"leveled_problem","data":{"title":"수준을 골라 풀어요","levels":{"기본":{"q":"교과서 예의 건물에서 1층과 2층에 쌓은 쌓기나무는 모두 몇 개일까요?","a":"21","steps":["1층 14개","2층 7개","14 + 7 = 21"]},"도전":{"q":"교과서 예의 건물에서 1층에 쌓은 쌓기나무는 3층보다 몇 개 더 많을까요?","a":"8","steps":["1층 14개","3층 6개","14 − 6 = 8"]},"심화":{"q":"모둠 친구들과 사용할 쌓기나무 개수를 정해 각자 건물을 쌓고, 내 건물을 층별 개수와 위, 앞, 옆에서 본 모양으로 소개하는 말을 써 봐요.","a":"여러 답 (예: 「저는 1층에 ○개, 2층에 ○개를 쌓았어요. 위에서 보면 …, 앞에서 보면 … 모양이에요.」)","open":true}},"tnote":{"ask":["기본에서 어느 층을 더했나요?","심화의 소개에 세 판이 모두 들어갔나요?"],"watch":"도전에서 두 수를 더하는 경우","min":5}},"suggested_extras":["q_l10_5","g_l10_1"]},{"id":"s13","stage":"응용문제","block":"offline_activity","data":{"title":"차곡차곡 건물 만들기","type":"group","goal":"「알지오매스 키즈」로 만들고 싶은 건물을 쌓기나무로 쌓고, 층별 개수와 위, 앞, 옆에서 본 모양으로 친구에게 소개하기","steps":["「알지오매스 키즈」에 들어가 쌓기나무 도구로 쌓는 방법과 지우는 방법을 익힌다","만들고 싶은 건물 모양을 생각한다","건물을 쌓기나무로 쌓고 방향 버튼으로 위, 앞, 옆에서 본 모양을 확인한다","층별 개수와 세 방향 모양으로 친구에게 소개한다"],"solo":["만들고 싶은 건물을 정해 공책에 위에서 본 모양을 그린다","자리마다 층 수를 써 넣는다","층별 개수와 앞·옆에서 본 모양을 써서 소개 글을 완성한다"],"materials":["컴퓨터 또는 태블릿 피시","쌓기나무(컴퓨터가 없을 때)","기록지"],"minutes":8,"tnote":{"ask":["건물을 소개할 때 무엇을 말했나요?","어려운 도구는 무엇이었나요?"],"watch":"쌓을 모양 구상이 어려운 모둠(예시를 따라 만든 뒤 조금 바꾸기)","min":8}},"suggested_extras":["g_l10_2","t_l10_4"]},{"id":"s14","stage":"응용문제","block":"real_world","data":{"title":"건축가의 모형 설계","scenario":{"icon":"🏗️","body":"건축가는 컴퓨터로 건물 모형을 만들어 여러 방향에서 돌려 보며 설계를 고쳐요. 화면 속 모형은 실제로 만들기 전에 모양을 확인하게 해 줘요."},"content":"공학 도구로 쌓기나무를 쌓으면 **여러 방향에서 본 모양**을 쉽게 확인할 수 있어요. 층별 개수를 더하면 **쌓기나무 개수**를 알 수 있어요."},"suggested_extras":["r_l10_2","r_l10_3"]},{"id":"s15","stage":"응용문제","block":"advanced_problem","data":{"title":"생각을 넓혀요","context":"교과서 41쪽 문제 3과 42쪽 문제 4는 둘 다 쌓기나무 9개로 쌓은 모양이에요.","challenge":"모둠 친구들이 같은 개수로 쌓은 건물이 서로 다른 모양이 되는 까닭은 무엇일까요?","note":"풀이: 쌓기나무를 놓는 자리와 자리마다 쌓는 높이가 다르면 모양이 달라져요 · 개수만으로는 모양이 하나로 정해지지 않아요 · **개수가 같아도 모양은 다를 수 있어요**","tnote":{"ask":["두 모양의 위에서 본 모양은 같나요?","모양을 하나로 정하려면 무엇이 필요할까요?"],"watch":"개수만 알면 똑같이 쌓을 수 있다고 여기는 경우","min":4}},"suggested_extras":["t_l10_5"]},{"id":"s16","stage":"정리","block":"exit_ticket","data":{"title":"오늘 확인해요","items":[{"q":"1층에 14개, 2층에 7개, 3층에 6개를 쌓은 건물은 쌓기나무가 모두 몇 개일까요?","a":"27"},{"q":"「알지오매스 키즈」에서 쌓기나무를 지우려면 어떤 도구를 고를까요?","a":"지우기 도구"},{"q":"교과서의 옆에서 본 모양은 어느 방향 버튼으로 본 모양과 같을까요?","a":"오른쪽"}],"self":["오늘 배운 것을 혼자 설명할 수 있어요","조금 헷갈려요","다시 배우고 싶어요"]},"suggested_extras":[]},{"id":"s17","stage":"정리","block":"summary","data":{"title":"오늘 배운 것","points":["쌓기나무 도구로 쌓고, 지우기 도구로 지워요.","방향 버튼으로 위, 앞, 옆(오른쪽)에서 본 모양을 확인해요.","층별 개수를 더하면 쌓기나무 개수예요.","화면 속에서 27개짜리 건물을 쌓아 세 방향 모양으로 소개했다."],"arrows":["쌓기","방향 버튼","소개하기"]},"suggested_extras":["r_l10_1"]},{"id":"s18","stage":"정리","block":"self_assessment","data":{"title":"스스로 점검해요","items":["📚 지식·이해 — 공학 도구로 여러 방향에서 본 모양을 확인할 수 있나요?","🔧 과정·기능 — 만든 건물을 층별 개수와 세 판으로 소개할 수 있나요?","💛 가치·태도 — 친구의 건물을 관심 있게 살펴보았나요?"],"prompts":["공학 도구와 실제 쌓기나무 가운데 더 좋았던 것과 까닭은?"]},"suggested_extras":["e_l10_3"]},{"id":"s19","stage":"정리","block":"next_lesson","data":{"title":"다음 시간엔","preview":"위, 앞, 옆에서 본 모양만으로는 쌓은 모양이 하나로 정해지지 않을 때가 있어요. 부족한 조건을 찾아 누가 쌓아도 똑같이 쌓게 해 봐요.","emoji":"🧐"},"suggested_extras":["c_l10_1"]}],"extras":[{"id":"v_l10_1","type":"video","icon":"🎥","title":"공학 도구 쌓기나무","url":"https://www.youtube.com/results?search_query=%EC%95%8C%EC%A7%80%EC%98%A4%EB%A7%A4%EC%8A%A4+%ED%82%A4%EC%A6%88+%EC%8C%93%EA%B8%B0%EB%82%98%EB%AC%B4+%EC%82%AC%EC%9A%A9%EB%B2%95","description":"쌓기·지우기·방향 버튼.","source":"유튜브 검색 (교사 사전 확인 권장)","fit_slides":["concept","motivate"]},{"id":"q_l10_1","type":"fun_question","icon":"💡","title":"쌓기","content":"쌓기나무는 어떻게 쌓을까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l10_2","type":"fun_question","icon":"💡","title":"지우기","content":"잘못 쌓은 쌓기나무는 어떻게 지울까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l10_3","type":"fun_question","icon":"💡","title":"위쪽 버튼","content":"위쪽 버튼으로 본 모양은?","fit_slides":["concept","basic_problem"]},{"id":"q_l10_4","type":"fun_question","icon":"💡","title":"27개","content":"1층 14·2층 7·3층 6이면 모두 몇 개?","fit_slides":["concept","basic_problem"]},{"id":"q_l10_5","type":"fun_question","icon":"💡","title":"같은 개수","content":"같은 개수로 다른 모양을 쌓을 수 있을까요?","fit_slides":["concept","basic_problem"]},{"id":"t_l10_1","type":"tip","icon":"🧩","title":"도구 익히기","content":"쌓기·지우기·방향 버튼을 먼저 충분히 익히게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l10_2","type":"tip","icon":"🧩","title":"초점","content":"도구를 능숙하게 다루기보다 생각한 모양을 나타내는 데 초점을 두세요(지도서 203).","fit_slides":["concept","misconception"]},{"id":"t_l10_3","type":"tip","icon":"🧩","title":"예시 따라","content":"구상이 어려우면 예시를 따라 만든 뒤 조금 바꾸게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l10_4","type":"tip","icon":"🧩","title":"간단한 모양부터","content":"도구가 어려우면 간단한 모양부터 만들게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l10_5","type":"tip","icon":"🧩","title":"자유 주제","content":"빨리 끝낸 학생에게는 건물 말고 다른 주제를 주세요.","fit_slides":["concept","misconception"]},{"id":"r_l10_1","type":"real_world","icon":"🌍","title":"건축 모형","content":"컴퓨터 설계.","fit_slides":["real_world","summary"]},{"id":"r_l10_2","type":"real_world","icon":"🌍","title":"게임 건축","content":"블록 게임 속 건물.","fit_slides":["real_world","summary"]},{"id":"r_l10_3","type":"real_world","icon":"🌍","title":"도시 모형","content":"입체 지도.","fit_slides":["real_world","summary"]},{"id":"g_l10_1","type":"game","icon":"🎮","title":"같은 개수 다른 모양","content":"모둠이 정한 개수로 서로 다른 모양 쌓기.","fit_slides":["leveled_problem","offline_activity"]},{"id":"g_l10_2","type":"game","icon":"🎮","title":"세 판 맞히기","content":"친구 건물의 세 판 맞히기.","fit_slides":["leveled_problem","offline_activity"]},{"id":"x_l10_1","type":"misconception","icon":"⚠️","title":"왼쪽 = 옆","content":"왼쪽 버튼 모양을 옆에서 본 모양으로 여기기.","fit_slides":["misconception","basic_problem"]},{"id":"x_l10_2","type":"misconception","icon":"⚠️","title":"층 수 = 개수","content":"층 수를 개수로 말하기.","fit_slides":["misconception","basic_problem"]},{"id":"e_l10_1","type":"example","icon":"📝","title":"도구 판","content":"쌓기·지우기·방향 버튼 그림을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l10_2","type":"example","icon":"📝","title":"건물 예","content":"1층 14·2층 7·3층 6 건물 소개 글을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l10_3","type":"example","icon":"📝","title":"같은 9개","content":"41쪽·42쪽 9개 두 모양을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"c_l10_1","type":"checklist","icon":"✅","title":"다음 시간 준비","content":"쌓기나무 10개를 챙깁니다.","fit_slides":["next_lesson"]}]};
  window.LESSONS["u2_l11"] = {"meta":{"grade":6,"subject":"수학","term":2,"unit":2,"unit_title":"공간과 입체","n":11,"title":"아리송아리송 쌓기나무 쌓기","std":"[6수03-10] 쌓기나무로 만든 입체도형의 위, 앞, 옆에서 본 모양을 표현할 수 있고, 이러한 표현을 보고 입체도형의 모양을 추측할 수 있다.","duration_min":40,"lesson_format":"생각이 반짝 수학 · 2세대 19장(7요소)","theme":"여러 방향에서 보는 공간","source":"2022 개정 수학 6-2 지도서 2단원(163~208쪽 · 『수학』 31~54 · 『수학익힘』 25~40) — 자기주도 원문 없이 지도서에서 세움 · 투영 회수 키 grade6/semester2/math/2단원_공간과입체/g6_math_u2_l10_아리송아리송쌓기나무쌓기.html","src_key":"u2_l11"},"slides":[{"id":"s01","stage":"도입","block":"cover","data":{"title":"아리송아리송 쌓기나무 쌓기\n부족한 조건 찾기","emoji":"🧐"},"suggested_extras":["v_l11_1"]},{"id":"s02","stage":"도입","block":"review","data":{"title":"지난 시간엔 무엇을 했나요?","content":"지난 시간에는 쌓기나무로 **여러 가지 모양**을 만들었어요. 오늘은 위, 앞, 옆에서 본 모양으로 쌓은 모양을 찾고, **부족한 조건**을 더해 누가 쌓아도 똑같이 쌓게 해요.","items":[{"q":"1층에 14개, 2층에 7개, 3층에 6개를 쌓은 건물은 쌓기나무가 모두 몇 개일까요?","a":"27"},{"q":"「알지오매스 키즈」에서 쌓기나무를 지우려면 어떤 도구를 고를까요?","a":"지우기 도구"},{"q":"교과서의 옆에서 본 모양은 어느 방향 버튼으로 본 모양과 같을까요?","a":"오른쪽"}],"from":"u2_l10"},"suggested_extras":["q_l11_1"]},{"id":"s03","stage":"도입","block":"motivate","data":{"scene_title":"민수가 쌓은 모양 맞히기","desc":"민수가 쌓기나무로 쌓은 모양을 위, 앞, 옆에서 본 모양과, 위에서 본 모양(가, 나, 다, 라 자리)으로 나타냈어요. 위에서 본 모양의 뒷줄 왼쪽에는 2가 쓰여 있어요.","question":"이 그림만 보고 누구나 민수와 똑같이 쌓을 수 있을까요? 개수를 알 수 있는 자리부터 찾아볼까요?","img":"assets/photo/math/block_puzzle_conditions.jpg","tnote":{"ask":["알고 있는 것은 무엇인가요?","개수를 바로 알 수 있는 자리는?"],"watch":"아무 수나 넣어 쌓는 경우","min":3}},"suggested_extras":["q_l11_2","r_l11_1"]},{"id":"s04","stage":"전개","block":"concept","data":{"fig":{"k":"skp","h":[[2,3,1],[2,2,0]],"show":["num","front","side"],"marks":{"0,0":"2","0,1":"가","0,2":"나","1,0":"다","1,1":"라"}},"title":"알고 있는 것","content":"알고 있는 것은 쌓은 모양을 **위, 앞, 옆에서 본 모양**이에요.\n위에서 본 모양을 보고 **쌓기나무 2개가 쌓여 있는 자리**(뒷줄 왼쪽)를 알 수 있어요.","tnote":{"ask":["2는 어느 자리인가요?","앞에서 본 모양은 몇 층까지인가요?"],"watch":"세 판을 따로따로만 보는 경우","min":4}},"suggested_extras":["e_l11_1"]},{"id":"s05","stage":"전개","block":"concept","data":{"fig":{"k":"skp","h":[[2,3,1],[2,2,0]],"show":["num","front","side"],"marks":{"0,0":"2","0,1":"가","0,2":"나","1,0":"다","1,1":"라"}},"title":"정해지는 자리부터","content":"앞에서 본 모양의 오른쪽 줄은 1층이고 그 줄에 자리가 나 하나뿐이라 **나 = 1**이에요.\n앞에서 본 가운데 줄은 3층인데 옆에서 본 앞줄은 2층까지라 3층은 뒷줄인 **가 = 3**이에요.","tnote":{"ask":["나는 왜 1개인가요?","가는 왜 3개인가요?"],"watch":"가와 라를 바꾸어 정하는 경우","min":4}},"suggested_extras":["t_l11_1"]},{"id":"s06","stage":"전개","block":"concept","data":{"fig":{"k":"u6r","items":[{"k":"skp","h":[[2,3,1],[2,1,0]],"show":["num"],"cap":"9개"},{"k":"skp","h":[[2,3,1],[1,2,0]],"show":["num"],"cap":"9개"},{"k":"skp","h":[[2,3,1],[2,2,0]],"show":["num"],"cap":"10개"}]},"title":"정해지지 않는 자리 — 경우를 모두","content":"다와 라는 옆에서 본 앞줄 2층보다 높을 수 없어 **1개나 2개**이고, 앞줄에 2층이 보이려면 **적어도 하나는 2개**예요.\n그래서 (다, 라) = (2, 1), (1, 2), (2, 2) **세 경우**이고 쌓기나무는 각각 9개, 9개, 10개예요.","tnote":{"ask":["세 경우 모두 세 판이 같나요?","다·라가 둘 다 1이면 어떻게 될까요?"],"watch":"한 경우만 찾고 멈추는 경우","min":4}},"suggested_extras":["e_l11_2","t_l11_2"]},{"id":"s07","stage":"전개","block":"concept","data":{"fig":{"k":"skp","h":[[2,3,1],[2,2,0]],"show":["iso","num"]},"title":"부족한 조건 더하기","content":"누가 쌓아도 똑같이 쌓으려면 조건이 더 필요해요.\n「쌓기나무를 **10개** 사용했다」면 다 2개, 라 2개로 **하나로 정해져요**.\n「**9개**」라면 아직 두 가지라 「라에 쌓기나무 2개」 같은 조건이 더 필요해요.","tnote":{"ask":["10개 조건이면 몇 가지가 남나요?","9개면 어떤 조건을 더할까요?"],"watch":"이미 정해진 가·나 자리를 조건으로 내는 경우","min":4}},"suggested_extras":["q_l11_3"]},{"id":"s08","stage":"전개","block":"misconception","data":{"title":"이런 생각을 조심해요","label":"자주 하는 생각","wrong":"세 판으로 정해지지 않는 다와 라 자리에는 **아무 수나** 넣어도 된다.","right":"다와 라는 옆에서 본 앞줄이 **2층**이라 2개보다 많을 수 없고, 앞줄에 2층이 보이려면 **적어도 하나는 2개**여야 해요. 조건을 지키며 **경우를 모두** 찾아야 해요.","hint":"다·라에 3개를 놓아 보고 세 판이 어떻게 달라지는지 확인하게 하세요.","tnote":{"ask":["다에 3개를 놓으면 옆에서 본 모양은?","다·라 둘 다 1이면?"],"watch":"정해지는 자리부터 정하지 않는 경우","min":3}},"suggested_extras":["x_l11_1","x_l11_2"]},{"id":"s09","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ①","scenario":{"icon":"🧊","body":"민수가 쌓은 모양을 위, 앞, 옆에서 본 모양과 위에서 본 모양(가, 나, 다, 라)으로 나타냈어요."},"question":"나 자리에 쌓인 쌓기나무는 몇 개일까요?","fig":{"k":"skp","h":[[2,3,1],[2,2,0]],"show":["num","front","side"],"marks":{"0,0":"2","0,1":"가","0,2":"나","1,0":"다","1,1":"라"}},"input":"count_input","answer":1,"note":"풀이: 앞에서 본 오른쪽 줄은 1층 · 그 줄에는 나 자리 하나뿐 → 1 → **1**"},"suggested_extras":["t_l11_3"]},{"id":"s10","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ②","scenario":{"icon":"🧊","body":"같은 그림이에요."},"question":"가 자리에 쌓인 쌓기나무는 몇 개일까요?","fig":{"k":"skp","h":[[2,3,1],[2,2,0]],"show":["num","front","side"],"marks":{"0,0":"2","0,1":"가","0,2":"나","1,0":"다","1,1":"라"}},"input":"count_input","answer":3,"note":"풀이: 앞에서 본 가운데 줄은 3층 · 옆에서 본 앞줄은 2층까지 → 가 = 3 → **3**"},"suggested_extras":["e_l11_3"]},{"id":"s11","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ③","scenario":{"icon":"🧊","body":"같은 그림이에요. 쌓기나무를 10개 사용했다는 조건을 더했어요."},"question":"다와 라 자리에 쌓인 쌓기나무는 각각 몇 개일까요?","fig":{"k":"skp","h":[[2,3,1],[2,2,0]],"show":["num","front","side"],"marks":{"0,0":"2","0,1":"가","0,2":"나","1,0":"다","1,1":"라"}},"options":[{"text":"다 1개, 라 1개"},{"text":"다 2개, 라 1개"},{"text":"다 1개, 라 2개"},{"text":"다 2개, 라 2개","correct":true}],"note":"풀이: 정해지는 자리 2 + 3 + 1 = 6 · 10 − 6 = 4 → 다 2, 라 2 → **다 2개, 라 2개**"},"suggested_extras":["q_l11_4"]},{"id":"s12","stage":"기본문제","block":"leveled_problem","data":{"title":"수준을 골라 풀어요","levels":{"기본":{"q":"민수가 쌓은 모양이 될 수 있는 경우는 모두 몇 가지일까요?","a":"3","steps":["다·라는 1개나 2개","적어도 하나는 2개","(2, 1) · (1, 2) · (2, 2) → 3가지"]},"도전":{"q":"쌓기나무를 9개 사용했고 라에 2개를 쌓았다면 다에는 몇 개를 쌓았을까요?","a":"1","steps":["정해지는 자리 6개","9 − 6 = 3개가 다와 라에","3 − 2 = 1"]},"심화":{"q":"세 판만으로는 모양이 정해지지 않는 쌓은 모양을 하나 만들고, 하나로 정해지게 하는 조건을 짝에게 내 봐요.","a":"여러 답 (예: 교과서 44쪽 문제 2 모양 + 「쌓기나무 10개」)","open":true}},"tnote":{"ask":["기본에서 경우를 빠짐없이 찾았나요?","심화에서 낸 조건으로 하나로 정해지나요?"],"watch":"도전에서 9 − 2로 셈하는 경우","min":5}},"suggested_extras":["q_l11_5","g_l11_1"]},{"id":"s13","stage":"응용문제","block":"offline_activity","data":{"title":"조건 카드 놀이","type":"group","goal":"모둠이 세 판으로 정해지지 않는 쌓은 모양을 만들고, 다른 모둠이 경우를 모두 찾은 뒤 조건 카드를 더해 하나로 좁히기","steps":["모둠이 쌓기나무로 모양을 쌓고 위, 앞, 옆에서 본 모양 카드를 만든다","다른 모둠이 세 판에 맞는 경우를 모두 찾아 위에서 본 모양에 수로 쓴다","처음 모둠이 조건 카드(전체 개수·한 자리의 개수)를 하나씩 낸다","하나로 정해지면 쌓아서 세 판과 견주어 확인한다"],"solo":["교과서 50쪽 민수의 세 판을 공책에 그린다","정해지는 자리부터 수를 쓰고 남은 자리의 경우를 모두 쓴다","하나로 정해지는 조건을 두 가지 만들어 쓴다"],"materials":["쌓기나무","세 판 카드","조건 카드"],"minutes":8,"tnote":{"ask":["경우를 모두 찾았나요?","조건 한 장으로 하나로 정해졌나요?"],"watch":"이미 정해진 자리를 조건으로 내는 모둠","min":8}},"suggested_extras":["g_l11_2","t_l11_4"]},{"id":"s14","stage":"응용문제","block":"real_world","data":{"title":"택배 상자 쌓기 지시서","scenario":{"icon":"📋","body":"창고에서 상자를 쌓을 때 위, 앞, 옆 그림만 주면 사람마다 다르게 쌓을 수 있어 「상자 몇 개」 같은 조건을 함께 적어요."},"content":"세 판으로 정해지는 자리부터 정하고, 정해지지 않는 자리는 **경우를 모두** 찾은 뒤 **전체 개수 같은 조건**을 더해 하나로 좁혀요."},"suggested_extras":["r_l11_2","r_l11_3"]},{"id":"s15","stage":"응용문제","block":"advanced_problem","data":{"title":"생각을 넓혀요","context":"민수가 쌓은 모양에서 친구가 「쌓기나무를 9개 사용했어」라고 조건을 더했어요.","challenge":"누가 쌓아도 똑같이 쌓으려면 조건이 더 필요한 까닭은 무엇이고, 어떤 조건을 더하면 좋을까요?","note":"풀이: 9개이면 (다, 라) = (2, 1), (1, 2) 두 가지 · 「라에 쌓기나무 2개」를 더하면 다 1, 라 2로 하나 · **라에 쌓기나무 2개**","tnote":{"ask":["9개일 때 몇 가지가 남나요?","가나 나의 개수를 조건으로 내면 될까요?"],"watch":"조건이 더 필요 없다고 하는 경우","min":4}},"suggested_extras":["t_l11_5"]},{"id":"s16","stage":"정리","block":"exit_ticket","data":{"title":"오늘 확인해요","items":[{"q":"민수가 쌓은 모양에서 나 자리에 쌓인 쌓기나무는 몇 개일까요?","a":"1"},{"q":"민수가 쌓은 모양이 될 수 있는 경우 가운데 쌓기나무가 가장 많이 드는 것은 몇 개일까요?","a":"10"},{"q":"누가 쌓아도 민수와 똑같이 쌓으려면 더 필요한 조건 하나를 말하면 무엇일까요?","a":"쌓기나무 10개를 사용했다"}],"self":["오늘 배운 것을 혼자 설명할 수 있어요","조금 헷갈려요","다시 배우고 싶어요"]},"suggested_extras":[]},{"id":"s17","stage":"정리","block":"summary","data":{"title":"오늘 배운 것","points":["세 판으로 정해지는 자리부터 정해요.","정해지지 않는 자리는 조건을 지키며 경우를 모두 찾아요.","전체 개수 같은 조건을 더하면 하나로 정해져요.","민수가 쌓은 모양을 세 가지에서 하나로 좁혔다."],"arrows":["정해지는 자리","경우 모두 찾기","조건 더하기"]},"suggested_extras":["r_l11_1"]},{"id":"s18","stage":"정리","block":"self_assessment","data":{"title":"스스로 점검해요","items":["📚 지식·이해 — 정해지는 자리와 정해지지 않는 자리를 가를 수 있나요?","🔧 과정·기능 — 경우를 모두 찾고 조건을 더할 수 있나요?","💛 가치·태도 — 친구의 설명을 듣고 궁금한 점을 질문했나요?"],"prompts":["조건을 만들 때 가장 신경 쓴 점은?"]},"suggested_extras":["e_l11_3"]},{"id":"s19","stage":"정리","block":"next_lesson","data":{"title":"다음 시간엔","preview":"이 단원에서 배운 내용을 문제로 마무리해요. 같은 꽃병을 찍은 사진끼리 짝 지을 수 있을까요?","emoji":"🏁"},"suggested_extras":["c_l11_1"]}],"extras":[{"id":"v_l11_1","type":"video","icon":"🎥","title":"부족한 조건 찾기","url":"https://www.youtube.com/results?search_query=%EC%B4%88%EB%93%B1+6%ED%95%99%EB%85%84+%EC%9C%84+%EC%95%9E+%EC%98%86%EC%97%90%EC%84%9C+%EB%B3%B8+%EB%AA%A8%EC%96%91+%EB%B3%B4%EA%B3%A0+%EC%8C%93%EA%B8%B0%EB%82%98%EB%AC%B4+%EA%B0%9C%EC%88%98+%EC%A0%95%ED%95%98%EA%B8%B0","description":"조건 더해 하나로.","source":"유튜브 검색 (교사 사전 확인 권장)","fit_slides":["concept","motivate"]},{"id":"q_l11_1","type":"fun_question","icon":"💡","title":"알고 있는 것","content":"무엇을 알고 있나요?","fit_slides":["concept","basic_problem"]},{"id":"q_l11_2","type":"fun_question","icon":"💡","title":"나 자리","content":"나는 몇 개일까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l11_3","type":"fun_question","icon":"💡","title":"가 자리","content":"가는 왜 3개일까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l11_4","type":"fun_question","icon":"💡","title":"경우","content":"다·라는 몇 가지가 될까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l11_5","type":"fun_question","icon":"💡","title":"조건","content":"하나로 정하려면 무엇이 더 필요할까요?","fit_slides":["concept","basic_problem"]},{"id":"t_l11_1","type":"tip","icon":"🧩","title":"수 써넣기","content":"위에서 본 모양에 수를 써넣고 세 판이 되는지 확인하게 하세요(지도서 205).","fit_slides":["concept","misconception"]},{"id":"t_l11_2","type":"tip","icon":"🧩","title":"구분하기","content":"개수를 알 수 있는 곳과 없는 곳을 구분하게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l11_3","type":"tip","icon":"🧩","title":"직접 쌓기","content":"여러 모양이 나오는 것을 쌓기나무로 직접 쌓아 보게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l11_4","type":"tip","icon":"🧩","title":"질문하기","content":"친구 설명을 듣고 궁금한 점을 질문하게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l11_5","type":"tip","icon":"🧩","title":"여러 개 그리기","content":"모양이 여러 개 나올 수 있는 세 판을 그려 보게 하세요.","fit_slides":["concept","misconception"]},{"id":"r_l11_1","type":"real_world","icon":"🌍","title":"쌓기 지시서","content":"상자 개수 조건.","fit_slides":["real_world","summary"]},{"id":"r_l11_2","type":"real_world","icon":"🌍","title":"퍼즐 게임","content":"조건으로 칸 채우기.","fit_slides":["real_world","summary"]},{"id":"r_l11_3","type":"real_world","icon":"🌍","title":"건축 허가","content":"층수 조건.","fit_slides":["real_world","summary"]},{"id":"g_l11_1","type":"game","icon":"🎮","title":"조건 카드","content":"조건을 하나씩 더해 하나로 좁히기.","fit_slides":["leveled_problem","offline_activity"]},{"id":"g_l11_2","type":"game","icon":"🎮","title":"경우 찾기 경주","content":"가능한 경우 빨리 모두 쓰기.","fit_slides":["leveled_problem","offline_activity"]},{"id":"x_l11_1","type":"misconception","icon":"⚠️","title":"아무 수나","content":"정해지지 않는 자리에 아무 수나 넣기.","fit_slides":["misconception","basic_problem"]},{"id":"x_l11_2","type":"misconception","icon":"⚠️","title":"정해진 자리 조건","content":"이미 정해진 자리를 조건으로 내기.","fit_slides":["misconception","basic_problem"]},{"id":"e_l11_1","type":"example","icon":"📝","title":"민수 세 판","content":"위·앞·옆과 가·나·다·라 판을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l11_2","type":"example","icon":"📝","title":"세 경우","content":"9개·9개·10개 수 쓴 그림을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l11_3","type":"example","icon":"📝","title":"조건 카드","content":"「10개」「라에 2개」 카드를 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"c_l11_1","type":"checklist","icon":"✅","title":"다음 시간 준비","content":"단원에서 헷갈렸던 문제를 하나 골라 옵니다.","fit_slides":["next_lesson"]}]};
  window.LESSONS["u2_l12"] = {"meta":{"grade":6,"subject":"수학","term":2,"unit":2,"unit_title":"공간과 입체","n":12,"title":"문제로 마무리","std":"[6수03-09] 쌓기나무로 만든 입체도형을 보고 사용된 쌓기나무의 개수를 구할 수 있다. [6수03-10] 쌓기나무로 만든 입체도형의 위, 앞, 옆에서 본 모양을 표현할 수 있고, 이러한 표현을 보고 입체도형의 모양을 추측할 수 있다.","duration_min":40,"lesson_format":"단원 마무리 · 2세대 19장(7요소)","theme":"여러 방향에서 보는 공간","source":"2022 개정 수학 6-2 지도서 2단원(163~208쪽 · 『수학』 31~54 · 『수학익힘』 25~40) — 자기주도 원문 없이 지도서에서 세움 · 투영 회수 키 grade6/semester2/math/2단원_공간과입체/g6_math_u2_l11_스스로마무리해요.html","src_key":"u2_l12"},"slides":[{"id":"s01","stage":"도입","block":"cover","data":{"title":"문제로 마무리\n공간과 입체","emoji":"🏁"},"suggested_extras":["v_l12_1"]},{"id":"s02","stage":"도입","block":"review","data":{"title":"지난 시간엔 무엇을 했나요?","content":"지난 시간에는 부족한 조건을 더해 쌓은 모양을 **하나로** 좁혔어요. 오늘은 이 단원에서 배운 **여러 방향에서 본 모양 · 쌓기나무 개수 · 쌓은 모양**을 문제로 정리해요.","items":[{"q":"민수가 쌓은 모양에서 나 자리에 쌓인 쌓기나무는 몇 개일까요?","a":"1"},{"q":"민수가 쌓은 모양이 될 수 있는 경우 가운데 쌓기나무가 가장 많이 드는 것은 몇 개일까요?","a":"10"},{"q":"누가 쌓아도 민수와 똑같이 쌓으려면 더 필요한 조건 하나를 말하면 무엇일까요?","a":"쌓기나무 10개를 사용했다"}],"from":"u2_l11"},"suggested_extras":["q_l12_1"]},{"id":"s03","stage":"도입","block":"motivate","data":{"scene_title":"공간과 입체 정리 판","desc":"교실 정리 판에 이 단원에서 만난 장면이 붙어 있어요 — 판다 바위, 해태 조각상, 떡 탑, 층별 건물 안내도, 로봇 공장, 민수가 쌓은 모양.","question":"각 장면에서 배운 것을 한 문장으로 말할 수 있을까요? 가장 자신 있는 것과 다시 보고 싶은 것은 무엇일까요?","img":"assets/photo/math/space_review_board.jpg","tnote":{"ask":["가장 자신 있는 장면은?","다시 보고 싶은 것은?"],"watch":"배운 내용을 장면 이름으로만 말하는 경우","min":3}},"suggested_extras":["q_l12_2","r_l12_1"]},{"id":"s04","stage":"전개","block":"concept","data":{"fig":{"k":"tools","items":[{"name":"가 — 손잡이 보이는 옆모습"},{"name":"나 — 위에서 본 모습"},{"name":"다 — 손잡이가 안 보이는 모습"},{"name":"라 — 손잡이 보이는 옆모습"}]},"title":"같은 꽃병 찾기","content":"마무리 1번 — 꽃병 2개의 사진을 2장씩 찍었어요.\n가는 다와 같은 모양으로 보이는 방향이 있어 **가와 다**, 나는 라를 위에서 본 모양이 될 수 있어 **나와 라**가 같은 꽃병이에요.\n라는 어느 방향에서 보아도 다처럼 손잡이가 보이지 않게 할 수 없어요.","tnote":{"ask":["가와 다는 왜 같은 꽃병일까요?","라를 위에서 보면?"],"watch":"손잡이 유무만으로 짝 짓는 경우","min":4}},"suggested_extras":["e_l12_1"]},{"id":"s05","stage":"전개","block":"concept","data":{"fig":{"k":"skp","h":[[0,1,0],[2,2,2],[1,2,0]],"show":["iso","top"]},"title":"세 판 그리기와 개수","content":"마무리 2번 — 앞에서 본 모양 1층, 1층, 2층, 옆에서 본 모양 1층, 1층, 2층이에요.\n마무리 3번 — 위에서 본 모양을 보면 가려진 자리에 1개가 더 있어 1 + 2 + 2 + 2 + 1 + 2 = **10개**예요.\n8개나 9개라고 하면 가려진 자리를 빠뜨린 거예요.","tnote":{"ask":["가려진 자리는 어디인가요?","8개라고 한 친구에게 무슨 말을 해 줄까요?"],"watch":"보이는 것만 세는 경우","min":4}},"suggested_extras":["t_l12_1"]},{"id":"s06","stage":"전개","block":"concept","data":{"fig":{"k":"skp","h":[[3,2,0],[2,1,1],[0,1,1]],"show":["iso","layers"]},"title":"수 쓰기와 층별","content":"마무리 4번 — 위에서 본 모양에 수를 쓰면 3 + 2 + 2 + 1 + 2 + 1 + 1 = **12개**예요.\n마무리 6번 — 층별로 1층 7개, 2층 3개, 3층 1개 → 7 + 3 + 1 = **11개**예요.","tnote":{"ask":["3층 그림은 어떤 자리인가요?","층별 합은 몇 개인가요?"],"watch":"3층 모양을 잘못 나타낸 경우(2층 위에 더 쌓인 곳 찾기)","min":4}},"suggested_extras":["e_l12_2","t_l12_2"]},{"id":"s07","stage":"전개","block":"concept","data":{"fig":{"k":"skp","h":[[3,1,2],[1,0,0],[2,1,1]],"show":["num","front","side"]},"title":"쌓은 모양 찾기와 세 판","content":"마무리 7번 — 세 판(앞 1층·2층·3층, 옆 1층·3층)은 쌓기나무 **7개**, 수 쓴 그림(뒷줄 2, 3, 3 / 앞줄 2)은 **10개**로 쌓은 모양과 이어요.\n마무리 8번 — 수 쓴 그림을 보고 앞에서 본 모양은 왼쪽부터 3층, 1층, 2층, 옆에서 본 모양은 2층, 1층, 3층이에요.","tnote":{"ask":["앞과 옆을 바꾸어 그리지 않았나요?","옆에서 본 모양의 왼쪽은 어느 줄인가요?"],"watch":"앞과 옆에서 본 모양을 바꾸어 그린 경우","min":4}},"suggested_extras":["q_l12_3"]},{"id":"s08","stage":"전개","block":"misconception","data":{"title":"이런 생각을 조심해요","label":"자주 하는 생각","wrong":"마무리 8번처럼 수 쓴 그림을 보고 그릴 때 **앞에서 본 모양과 옆에서 본 모양**을 바꾸어 그려도 같다.","right":"앞에서 본 모양은 **왼쪽 줄부터** 줄마다 가장 높은 층, 옆에서 본 모양은 오른쪽에서 보아 **앞줄이 가장 왼쪽**이에요. 마무리 8번은 앞 3층, 1층, 2층, 옆 2층, 1층, 3층이에요.","hint":"수 쓴 그림대로 쌓아 앞과 오른쪽에서 직접 보게 하세요.","tnote":{"ask":["앞에서 본 모양의 왼쪽 줄은?","옆에서 본 모양의 왼쪽 줄은?"],"watch":"앞에서 본 모양 그대로 옆을 그리는 경우","min":3}},"suggested_extras":["x_l12_1","x_l12_2"]},{"id":"s09","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ①","scenario":{"icon":"🧊","body":"마무리 3번 — 쌓은 모양과 위에서 본 모양이에요."},"question":"똑같이 쌓을 때 필요한 쌓기나무는 몇 개일까요?","fig":{"k":"skp","h":[[0,1,0],[2,2,2],[1,2,0]],"show":["iso","top"]},"input":"count_input","answer":10,"note":"풀이: 가려진 자리 1곳에 1개 · 1 + 2 + 2 + 2 + 1 + 2 = 10 → **10**"},"suggested_extras":["t_l12_3"]},{"id":"s10","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ②","scenario":{"icon":"🧊","body":"마무리 4번 — 쌓은 모양과 위에서 본 모양이에요."},"question":"위에서 본 모양에 수를 써서 구하면 쌓기나무는 몇 개일까요?","fig":{"k":"skp","h":[[3,2,0],[2,1,2],[1,0,1]],"show":["iso","top"]},"input":"count_input","answer":12,"note":"풀이: 뒷줄 3, 2 · 가운데 줄 2, 1, 2 · 앞줄 1, 1 · 3 + 2 + 2 + 1 + 2 + 1 + 1 = 12 → **12**"},"suggested_extras":["e_l12_3"]},{"id":"s11","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ③","scenario":{"icon":"🧊","body":"마무리 8번 — 위에서 본 모양에 수를 쓴 그림이에요."},"question":"옆에서 본 모양을 왼쪽부터 층으로 나타내면 무엇일까요?","fig":{"k":"skp","h":[[3,1,2],[1,0,0],[2,1,1]],"show":["num"],"ask":["side"]},"options":[{"text":"3층, 1층, 2층"},{"text":"2층, 1층, 3층","correct":true},{"text":"1층, 1층, 3층"},{"text":"6층, 1층, 4층"}],"note":"풀이: 옆은 오른쪽에서 본 모양 — 앞줄이 가장 왼쪽 · 앞줄 2, 가운데 줄 1, 뒷줄 3 → **2층, 1층, 3층**"},"suggested_extras":["q_l12_4"]},{"id":"s12","stage":"기본문제","block":"leveled_problem","data":{"title":"수준을 골라 풀어요","levels":{"기본":{"q":"마무리 6번 — 층별로 1층 7개, 2층 3개, 3층 1개면 쌓기나무는 모두 몇 개일까요?","a":"11","steps":["층마다 더해요","7 + 3 + 1","11"]},"도전":{"q":"마무리 8번 수 쓴 그림(뒷줄 3, 1, 2 / 가운데 줄 1 / 앞줄 2, 1, 1)으로 쌓은 쌓기나무는 모두 몇 개일까요?","a":"11","steps":["쓴 수를 모두 더해요","3 + 1 + 2 + 1 + 2 + 1 + 1","11"]},"심화":{"q":"이 단원에서 배운 네 가지 표현으로 같은 모양을 나타내고, 하나로 정해지는 표현과 아닌 표현을 견주어 말해 봐요.","a":"여러 답 (예: 수 쓴 그림·층별 그림은 하나로 · 위·앞·옆은 여러 가지일 수 있음)","open":true}},"tnote":{"ask":["기본에서 층마다 더했나요?","심화에서 네 표현을 모두 다루었나요?"],"watch":"도전에서 줄 수를 세는 경우","min":5}},"suggested_extras":["q_l12_5","g_l12_1"]},{"id":"s13","stage":"응용문제","block":"offline_activity","data":{"title":"공간과 입체 문제 만들기","type":"group","goal":"모둠이 쌓기나무로 모양을 쌓아 단원 문제(세 판·개수·층별·조건)를 만들고 다른 모둠과 바꾸어 풀기","steps":["모둠이 쌓기나무로 모양 하나를 쌓는다","세 판 그리기·개수 구하기·층별 그림·조건 찾기 문제를 한 장씩 만든다","다른 모둠과 문제를 바꾸어 풀고 쌓아서 확인한다","가장 헷갈렸던 문제를 골라 반 전체에 소개한다"],"solo":["쌓기나무로 모양 하나를 쌓는다","세 판·수 쓴 그림·층별 그림을 모두 그린다","개수를 세 가지 방법으로 구해 같은지 확인한다"],"materials":["쌓기나무","모눈 카드","색연필"],"minutes":8,"tnote":{"ask":["세 방법으로 구한 개수가 같았나요?","바꾸어 푼 문제에서 헷갈린 곳은?"],"watch":"문제를 만들고 답을 확인하지 않는 모둠","min":8}},"suggested_extras":["g_l12_2","t_l12_4"]},{"id":"s14","stage":"응용문제","block":"real_world","data":{"title":"드론 사진으로 세는 건물","scenario":{"icon":"🛸","body":"도시 계획을 세울 때 드론으로 위에서 찍은 사진과 건물 층수를 함께 보고 건물의 크기를 셈해요."},"content":"쌓은 모양은 **위·앞·옆에서 본 모양 · 쌓은 모양과 위에서 본 모양 · 수를 쓴 그림 · 층별 그림**으로 나타내요. 가려진 자리는 위에서 본 모양으로, 정해지지 않는 자리는 조건으로 풀어요."},"suggested_extras":["r_l12_2","r_l12_3"]},{"id":"s15","stage":"응용문제","block":"advanced_problem","data":{"title":"생각을 넓혀요","context":"마무리 5번 — 주어진 두 모양을 합쳐 만들 수 있는 모양을 세 가지 보기 가운데에서 찾아요.","challenge":"어떤 방법으로 찾으면 좋을까요?","note":"풀이: 보기 모양의 쌓기나무 개수가 두 모양의 개수 합과 같은지 보고, 보기 모양을 두 부분으로 나누어 주어진 두 모양으로 나뉘는지 확인해요 · 어려우면 쌓기나무로 직접 합쳐 봐요 · **두 부분으로 나누어 보기**","tnote":{"ask":["개수부터 견주었나요?","두 부분으로 어떻게 나누나요?"],"watch":"모양을 직접 합쳐 보지 않고 짐작만 하는 경우","min":4}},"suggested_extras":["t_l12_5"]},{"id":"s16","stage":"정리","block":"exit_ticket","data":{"title":"오늘 확인해요","items":[{"q":"마무리 1번에서 가와 같은 꽃병을 찍은 사진은 무엇일까요?","a":"다"},{"q":"마무리 3번 쌓은 모양은 쌓기나무가 몇 개일까요?","a":"10"},{"q":"마무리 8번에서 앞에서 본 모양을 왼쪽부터 층으로 나타내면 무엇일까요?","a":"3층, 1층, 2층"}],"self":["오늘 배운 것을 혼자 설명할 수 있어요","조금 헷갈려요","다시 배우고 싶어요"]},"suggested_extras":[]},{"id":"s17","stage":"정리","block":"summary","data":{"title":"오늘 배운 것","points":["같은 물체도 보는 방향에 따라 다르게 보여요 — 여러 방향을 모아요.","쌓기나무 개수는 위에서 본 모양·수 쓴 그림·층별 그림으로 정확히 구해요.","세 판으로 쌓은 모양을 떠올리고, 정해지지 않으면 조건을 더해요.","판다 바위에서 민수가 쌓은 모양까지, 공간을 여러 방향에서 보는 눈을 길렀다."],"arrows":["여러 방향","개수","쌓은 모양"]},"suggested_extras":["r_l12_1"]},{"id":"s18","stage":"정리","block":"self_assessment","data":{"title":"스스로 점검해요","items":["📚 지식·이해 — 공간과 입체 단원을 잘 이해했나요?","🔧 과정·기능 — 쌓은 모양과 위, 앞, 옆에서 본 모양을 탐구하여 나타내고 쌓기나무 개수를 구할 수 있나요?","💛 가치·태도 — 생활 속 공간과 입체에 흥미와 관심이 생겼나요?"],"prompts":["단원 첫 시간에 쓴 나의 다짐을 잘 실천했나요?"]},"suggested_extras":["e_l12_3"]},{"id":"s19","stage":"정리","block":"next_lesson","data":{"title":"다음 단원엔","preview":"3단원 「소수의 나눗셈」에서는 (소수) ÷ (소수)를 계산하는 방법을 알아봐요. 나누는 수와 나누어지는 수의 소수점을 함께 옮기면 몫은 어떻게 될까요?","emoji":"➗"},"suggested_extras":["c_l12_1"]}],"extras":[{"id":"v_l12_1","type":"video","icon":"🎥","title":"공간과 입체 정리","url":"https://www.youtube.com/results?search_query=%EC%B4%88%EB%93%B1+6%ED%95%99%EB%85%84+%EA%B3%B5%EA%B0%84%EA%B3%BC+%EC%9E%85%EC%B2%B4+%EB%8B%A8%EC%9B%90+%EC%A0%95%EB%A6%AC+%EB%AC%B8%EC%A0%9C","description":"단원 핵심 정리.","source":"유튜브 검색 (교사 사전 확인 권장)","fit_slides":["concept","motivate"]},{"id":"q_l12_1","type":"fun_question","icon":"💡","title":"꽃병","content":"같은 꽃병 사진은 어떻게 찾을까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l12_2","type":"fun_question","icon":"💡","title":"가려진 자리","content":"8개라고 하면 무엇을 빠뜨렸을까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l12_3","type":"fun_question","icon":"💡","title":"층별","content":"3층 그림은 어떤 자리일까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l12_4","type":"fun_question","icon":"💡","title":"앞과 옆","content":"두 판을 바꾸어 그리면 어떻게 될까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l12_5","type":"fun_question","icon":"💡","title":"합치기","content":"합친 모양은 어떻게 찾을까요?","fit_slides":["concept","basic_problem"]},{"id":"t_l12_1","type":"tip","icon":"🧩","title":"오답 유형 1","content":"꽃병 짝을 못 찾으면 다른 방향에서 보일 부분을 생각하게 하세요(지도서 207).","fit_slides":["concept","misconception"]},{"id":"t_l12_2","type":"tip","icon":"🧩","title":"오답 유형 3","content":"8개·9개라고 하면 가려진 쌓기나무를 세게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l12_3","type":"tip","icon":"🧩","title":"오답 유형 4","content":"수 쓰기가 어려우면 똑같이 쌓아 자리마다 세게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l12_4","type":"tip","icon":"🧩","title":"오답 유형 8","content":"앞과 옆을 바꾸면 앞은 왼쪽, 옆은 오른쪽 기준임을 확인하게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l12_5","type":"tip","icon":"🧩","title":"채점","content":"세 판 문제는 세 판이 모두 맞을 때만 정답이에요.","fit_slides":["concept","misconception"]},{"id":"r_l12_1","type":"real_world","icon":"🌍","title":"드론 측량","content":"위에서 찍은 사진과 층수.","fit_slides":["real_world","summary"]},{"id":"r_l12_2","type":"real_world","icon":"🌍","title":"건축 모형","content":"여러 방향 도면.","fit_slides":["real_world","summary"]},{"id":"r_l12_3","type":"real_world","icon":"🌍","title":"물류 창고","content":"상자 개수 세기.","fit_slides":["real_world","summary"]},{"id":"g_l12_1","type":"game","icon":"🎮","title":"단원 빙고","content":"핵심 낱말 빙고.","fit_slides":["leveled_problem","offline_activity"]},{"id":"g_l12_2","type":"game","icon":"🎮","title":"문제 바꾸어 풀기","content":"모둠 문제 교환.","fit_slides":["leveled_problem","offline_activity"]},{"id":"x_l12_1","type":"misconception","icon":"⚠️","title":"가려진 자리 빠뜨림","content":"8개·9개로 답하기.","fit_slides":["misconception","basic_problem"]},{"id":"x_l12_2","type":"misconception","icon":"⚠️","title":"앞·옆 바꿈","content":"앞에서 본 모양과 옆에서 본 모양 바꾸어 그리기.","fit_slides":["misconception","basic_problem"]},{"id":"e_l12_1","type":"example","icon":"📝","title":"마무리 1~4","content":"꽃병·세 판·개수·수 쓰기 문제를 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l12_2","type":"example","icon":"📝","title":"마무리 5~8","content":"합치기·층별·잇기·세 판 문제를 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l12_3","type":"example","icon":"📝","title":"스스로 평가","content":"별 색칠 판을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"c_l12_1","type":"checklist","icon":"✅","title":"다음 단원 준비","content":"3단원 「소수의 나눗셈」 — 소수의 자릿값을 떠올려 옵니다.","fit_slides":["next_lesson"]}]};
